var Q19=[
{n:1,q:'La Constitución Española de 1978 se refiere a la Policía Judicial en su artículo:',o:{a:'123',b:'124',c:'125',d:'126'},correct:'d',why:{d:'El art. 126 CE regula la Policía Judicial, estableciendo su dependencia de Jueces, Tribunales y Ministerio Fiscal.'}},
{n:2,q:'En la Constitución Española de 1978 se dispone que...',o:{a:'La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal.',b:'Sus funciones son la averiguación del delito y descubrimiento y aseguramiento del delincuente, de acuerdo con lo que reglamentariamente se determine.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 126 CE establece la dependencia funcional y las funciones de averiguación y descubrimiento del delincuente.'}},
{n:3,q:'Con respecto a la Policía Judicial, señale la afirmación incorrecta:',o:{a:'No existe una única ley que regule y desarrolle a la Policía Judicial como tal, sino que son varios los cuerpos legales en los que está regulada.',b:'Todos los miembros de las Fuerzas y Cuerpos de Seguridad, cualquiera que sea su naturaleza y dependencia, formarán parte de las Unidades Orgánicas de Policía Judicial.',c:'La Policía Judicial no existe como cuerpo policial independiente, sino que se trata de una función específica que están llamados a cumplir los integrantes de las Fuerzas y Cuerpos de Seguridad.',d:'Hay que distinguir entre las funciones de Policía Judicial con carácter genérico, y las Unidades Orgánicas de Policía Judicial, que constituyen la Policía Judicial en sentido estricto.'},correct:'b',why:{b:'No todos los miembros forman parte de las Unidades Orgánicas; solo los específicamente adscritos. La opción b es incorrecta conforme a la LO 2/1986.'}},
{n:4,q:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, se refiere a la Policía Judicial...',o:{a:'En los artículos 29 a 36.',b:'En el capítulo V de su Título II.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'La LO 2/1986 regula la PJ en el Capítulo V de su Título II, que comprende los arts. 29 a 36.'}},
{n:5,q:'La Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad...',o:{a:'Opta por un modelo de dependencia funcional de la Policía Judicial respecto del Poder Judicial.',b:'Opta por un modelo de dependencia orgánica de la Policía Judicial respecto del Poder Judicial.',c:'Opta por un modelo de dependencia funcional de la Policía Judicial respecto del Gobierno.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'La LO 2/1986 opta por dependencia funcional de la PJ respecto del Poder Judicial, no orgánica.'}},
{n:6,q:'El artículo 29 Ley Orgánica 2/1986 de Fuerzas y Cuerpos de Seguridad, dispone que las funciones de Policía Judicial que se mencionan en el artículo 126 de la Constitución...',o:{a:'Serán ejercidas por las Fuerzas y Cuerpos de Seguridad del Estado, a través de las Unidades que se mencionan en ese capítulo.',b:'Que para ejercer esa función tendrán carácter colaborador de las Fuerzas y Cuerpos de Seguridad del Estado el personal de Policía de las Comunidades Autónomas y de las Corporaciones Locales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 29 LO 2/1986 establece ambas cosas: ejercicio por FFCCS del Estado y carácter colaborador de PJ autonómica y local.'}},
{n:7,q:'Con respecto a la Policía Judicial, señale la afirmación correcta:',o:{a:'Todos los miembros de las Fuerzas y Cuerpos de Seguridad, sean estatales, autonómicos o locales, pertenecen a la Policía Judicial genérica.',b:'Las Unidades Orgánicas de Policía Judicial se caracterizan por estar adscritas total o parcialmente a órganos jurisdiccionales.',c:'Las Unidades Orgánicas de Policía Judicial están integradas única y exclusivamente por miembros de los Cuerpos y Fuerzas de Seguridad del Estado.',d:'Todas las respuestas anteriores son correctas.'},correct:'a',why:{a:'Todos los miembros de las FFCCS pertenecen a la PJ en sentido genérico conforme al art. 126 CE y art. 29 LO 2/1986.'}},
{n:8,q:'Constituyen la Policía Judicial en sentido estricto:',o:{a:'Las Unidades Orgánicas integradas por miembros del Cuerpo Nacional de Policía y de la Guardia Civil.',b:'Todos los miembros de las Fuerzas y Cuerpos de Seguridad, cualquiera que sea su naturaleza y dependencia.',c:'Todos los miembros del Cuerpo Nacional de Policía y de la Guardia Civil.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'La PJ en sentido estricto la constituyen las Unidades Orgánicas integradas por miembros del CNP y de la Guardia Civil.'}},
{n:9,q:'Los funcionarios policiales, cuando realizan funciones de Policía Judicial tienen dependencia:',o:{a:'Orgánica con respecto a sus superiores jerárquicos, dentro de la Administración a la que pertenezcan.',b:'Funcional respecto de los jueces, tribunales y Ministerio Fiscal, para el cumplimiento de las funciones de Policía Judicial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'Los funcionarios de PJ tienen dependencia orgánica de sus superiores y dependencia funcional de jueces, tribunales y MF, según el art. 31 LO 2/1986.'}},
{n:10,q:'Para ocupar puestos en las Unidades Orgánicas de Policía Judicial, será requisito necesario:',o:{a:'La posesión del diploma correspondiente.',b:'La acreditación de las condiciones físicas exigidas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'Conforme al RD 769/1987, para pertenecer a las UO de PJ se requiere el diploma correspondiente y acreditar las condiciones físicas exigidas.'}},
{n:11,q:'En las diligencias o actuaciones que lleven a cabo por encargo y bajo la supervisión de Jueces, Tribunales o Fiscales competentes de lo penal, los funcionarios de la Policía Judicial:',o:{a:'Tendrán el carácter de auxiliares de dichos jueces.',b:'Tendrán el carácter de comisionados de dichos jueces.',c:'Tendrán el carácter de colaboradores de dichos jueces.',d:'Todas las respuestas anteriores son correctas.'},correct:'b',why:{b:'Según el art. 30 LO 2/1986, los funcionarios de PJ tendrán carácter de comisionados de los Jueces, Tribunales y Fiscales.'}},
{n:12,q:'Según el artículo 30 de la Ley Orgánica 2/1986, de FFCCS, las Unidades Orgánicas de Policía Judicial podrá adscribirse...',o:{a:'Al Ministerio Fiscal, oído el Fiscal General del Estado.',b:'Por el Ministerio del Interior, oído el Consejo General del Poder Judicial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'b',why:{b:'Según el art. 30 LO 2/1986, las UO de PJ se adscribirán por el Ministerio del Interior, oído el CGPJ.'}},
{n:13,q:'En el artículo 31 de la Ley Orgánica 2/1986, de FFCCS, se dispone que los Jueces o Presidentes de los respectivos órganos del orden jurisdiccional penal, podrán solicitar la intervención en una investigación de funcionarios o medios adscritos a Unidades orgánicas de Policía Judicial...',o:{a:'Por conducto del Presidente del Tribunal Supremo.',b:'Por conducto del Presidente del Tribunal Constitucional.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'d',why:{d:'Según el art. 31 LO 2/1986, la solicitud se hace por conducto del Presidente del TSJ o de los Presidentes de las Audiencias Provinciales, no del TS ni del TC.'}},
{n:14,q:'En el artículo 31 de la Ley Orgánica 2/1986, de FFCCS, se dispone que los Jueces o Presidentes de los respectivos órganos del orden jurisdiccional penal, podrán solicitar la intervención en una investigación de funcionarios o medios adscritos a Unidades orgánicas de Policía Judicial...',o:{a:'Por conducto de los Presidente de los Tribunales Superiores de Justicia.',b:'Por conducto de los Presidentes de las Audiencias Provinciales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 31 LO 2/1986 establece que la solicitud se hace por conducto del Presidente del TSJ o de los Presidentes de las Audiencias Provinciales.'}},
{n:15,q:'En el artículo 31 de la Ley Orgánica 2/1986, de FFCCS, se dispone que los Fiscales Jefes podrán solicitar la intervención en una investigación de funcionarios o medios adscritos a Unidades orgánicas de Policía Judicial...',o:{a:'Por conducto del Presidente de los Tribunales Superiores de Justicia.',b:'Por conducto del Fiscal General del Estado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'b',why:{b:'Según el art. 31 LO 2/1986, los Fiscales Jefes solicitan la intervención por conducto del Fiscal General del Estado.'}},
{n:16,q:'En el artículo 33 de la Ley Orgánica 2/1986, de FFCCS, se dispone que ...',o:{a:'Los funcionarios adscritos a las Unidades de Policía Judicial desempeñarán esa función con carácter exclusivo.',b:'Los funcionarios adscritos a las Unidades de Policía Judicial desempeñarán esa función con carácter exclusivo, sin perjuicio de que puedan desarrollar también las misiones de prevención de la delincuencia.',c:'Los funcionarios adscritos a las Unidades de Policía Judicial desempeñarán esa función con carácter exclusivo, sin perjuicio de que puedan desarrollar también las misiones de prevención de la delincuencia y demás que se les encomienden, cuando las circunstancias lo requieran, de entre las correspondientes a las Fuerzas y Cuerpos de Seguridad del Estado.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'c',why:{c:'El art. 33 LO 2/1986 establece función exclusiva pero sin perjuicio de misiones de prevención y demás que se les encomienden cuando las circunstancias lo requieran.'}},
{n:17,q:'En el artículo 34 de la Ley Orgánica 2/1986, de FFCCS, se dispone que ...',o:{a:'Los funcionarios de las Unidades de Policía Judicial no podrán ser removidos o apartados de la investigación concreta que se les hubiera encomendado, sin autorización del Jefe de su Unidad respectiva.',b:'Los funcionarios de las Unidades de Policía Judicial no podrán ser removidos o apartados de la investigación concreta que se les hubiera encomendado, hasta que finalice la misma o la fase del procedimiento judicial que la originara, si no es por decisión o con la autorización del Juez o Fiscal competente.',c:'Los funcionarios de las Unidades de Policía Judicial no podrán ser removidos o apartados de la investigación concreta que se les hubiera encomendado en tanto permanezcan vinculados a la misma por orden o decisión de la autoridad judicial competente.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'b',why:{b:'El art. 34 LO 2/1986 establece que los funcionarios no podrán ser removidos hasta que finalice la investigación o la fase del procedimiento, salvo por decisión o autorización del Juez o Fiscal competente.'}},
{n:18,q:'El Diploma que acredita la obtención del título de funcionario de Policía Judicial es expedido:',o:{a:'Por el Consejo General del Poder Judicial.',b:'Por el Centro de Estudios Judiciales.',c:'Por el Ministro de Justicia.',d:'Por el Ministro de Interior.'},correct:'b',why:{b:'El Diploma de Policía Judicial es expedido por el Centro de Estudios Judiciales.'}},
{n:19,q:'Según el artículo 35 de la Ley Orgánica 2/1986, de FFCCS, los Jueces y Tribunales de lo Penal y el Ministerio Fiscal tendrán las facultades de ...',o:{a:'Darles las órdenes e instrucciones que sean necesarias, en ejecución de lo dispuesto en las normas de Enjuiciamiento Criminal y Estatutos del Ministerio Fiscal.',b:'Instar el ejercicio de la potestad disciplinaria, emitiendo los informes que puedan exigir la tramitación de los correspondientes expedientes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 35 LO 2/1986 otorga tanto la facultad de dar órdenes e instrucciones como la de instar la potestad disciplinaria.'}},
{n:20,q:'Según el artículo 35 de la Ley Orgánica 2/1986, de FFCCS, los Jueces y Tribunales de lo Penal y el Ministerio Fiscal tendrán las facultades de ...',o:{a:'Velar por el cumplimiento de las Leyes y demás disposiciones del Estado y garantizar el funcionamiento de los servicios públicos esenciales.',b:'Determinar, mediante órdenes o instrucciones, el contenido y circunstancias de las actuaciones que interesen a dichas Unidades.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'b',why:{b:'El art. 35 LO 2/1986 faculta para determinar mediante órdenes o instrucciones el contenido y circunstancias de las actuaciones. La opción a corresponde a otras funciones generales.'}},
{n:21,q:'La Policía Judicial, en la vigente Ley de Enjuiciamiento Criminal,...',o:{a:'Está regulada en el Título II de su Libro III.',b:'Comprende los artículos 282 a 298.',c:'Regula de forma metódica y detallada las Unidades Orgánicas.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'La PJ en la LECrim está regulada en el Título II del Libro III, comprende los arts. 282 a 298, y regula de forma metódica y detallada las Unidades Orgánicas.'}},
{n:22,q:'Según el art.282 de la Ley de Enjuiciamiento Criminal, la Policía Judicial tiene por objeto, y será obligación de todos los que la componen:',o:{a:'Averiguar los delitos públicos que se cometan en su territorio o demarcación.',b:'Practicar, según sus atribuciones, las diligencias necesarias para comprobar los delitos que se cometan en su territorio o demarcación y descubrir a los delincuentes.',c:'Recoger todos los efectos, instrumentos o pruebas del delito, de cuya desaparición hubiese peligro, poniéndolos a disposición de la autoridad judicial.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 282 LECrim establece todas estas obligaciones: averiguar delitos, practicar diligencias para comprobarlos y descubrir delincuentes, y recoger efectos del delito.'}},
{n:23,q:'Según el art.282 de la Ley de Enjuiciamiento Criminal, cuando las víctimas entren en contacto con la Policía Judicial:',o:{a:'Cumplirá con los deberes de información que prevé la legislación vigente.',b:'Llevará a cabo una valoración de las circunstancias particulares de las víctimas para determinar provisionalmente qué medidas de protección deben ser adoptadas para garantizarles una protección adecuada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 282 LECrim establece que la PJ cumplirá los deberes de información y llevará a cabo la valoración de circunstancias para determinar medidas de protección.'}},
{n:24,q:'Según el art.282 de la Ley de Enjuiciamiento Criminal, si el delito fuera de los que solo pueden perseguirse a instancia de parte legítima...',o:{a:'Tendrán la misma obligación que en los delitos públicos, si se les requiere al efecto.',b:'Realizarán el ofrecimiento de acciones a la presunta víctima antes de proceder a las funciones de averiguación del delito y descubrimiento del delincuente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 282 LECrim establece que la PJ tendrá la misma obligación si se le requiere y realizará el ofrecimiento de acciones a la víctima.'}},
{n:25,q:'Según el art.282 de la Ley de Enjuiciamiento Criminal, la ausencia de denuncia no impedirá la práctica de las primeras diligencias de prevención y aseguramiento de los delitos...',o:{a:'De violencia contra las mujeres.',b:'Relativos a la propiedad intelectual e industrial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 282 LECrim establece que la ausencia de denuncia no impedirá las primeras diligencias en delitos de violencia contra las mujeres ni relativos a la propiedad intelectual e industrial.'}},
{n:26,q:'El artículo 283 de la Ley de Enjuiciamiento Criminal, atribuye la condición de Policía Judicial a un grupo muy heterogéneo de personas, entre los que se hallan:',o:{a:'Los Alcaldes, Tenientes de Alcalde, Alcaldes de Barrio y los integrantes de las Policías Estatal, Autonómica y Local.',b:'Los guardas de montes y guardas jurados.',c:'Los funcionarios de prisiones.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 283 LECrim atribuye la condición de PJ a un grupo heterogéneo que incluye Alcaldes y sus tenientes, Policías de todos los niveles, guardas de montes y jurados, y funcionarios de prisiones.'}},
{n:27,q:'La Sentencia del Tribunal Supremo de 25-09-2003, considera:',o:{a:'Que el artículo 283 de la Ley de Enjuiciamiento Criminal debe entenderse expresamente derogado por lo dispuesto en la Ley Orgánica del Poder Judicial.',b:'Que el artículo 283 de la Ley de Enjuiciamiento Criminal debe entenderse tácitamente derogado por la legislación promulgada tras la Constitución de 1978.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'b',why:{b:'La STS de 25-09-2003 considera que el art. 283 LECrim debe entenderse tácitamente derogado por la legislación posterior a la CE de 1978.'}},
{n:28,q:'Según el artículo 284 de la LECrim., inmediatamente que los funcionarios de la Policía Judicial tuvieren conocimiento de un delito público o fueren requeridos para prevenir la instrucción de diligencias por algún delito privado:',o:{a:'Lo participarán a la autoridad judicial o al Ministerio Fiscal, si pudieren hacerlo sin cesar en la práctica de las diligencias de prevención.',b:'Lo participarán a sus mandos naturales, sin perjuicio de la comunicación que corresponda a la autoridad judicial.',c:'Lo participarán a los Cuerpos de Seguridad del Estado competentes en el territorio, sin cesar por ello las diligencias a prevención.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'El art. 284 LECrim establece que lo participarán a la autoridad judicial o al MF, si pudieren hacerlo sin cesar en la práctica de las diligencias de prevención.'}},
{n:29,q:'Según el artículo 284 de la Ley de Enjuiciamiento Criminal, como regla general, cuando no exista autor conocido de un delito, la policía judicial...',o:{a:'Archivará el atestado sin más trámite, dando cuenta al Ministerio Fiscal.',b:'Conservará el atestado a disposición del Ministerio Fiscal y de la Autoridad Judicial, sin enviárselo.',c:'Remitirá el atestado instruido a la autoridad judicial, advirtiendo de la posibilidad de proseguir las averiguaciones necesarias para el descubrimiento de su autor.',d:'Todas las respuestas anteriores son incorrectas.'},correct:'b',why:{b:'El art. 284 LECrim establece que cuando no exista autor conocido, la PJ conservará el atestado a disposición del MF y la Autoridad Judicial, sin enviárselo.'}},
{n:30,q:'Según el artículo 284 de la Ley de Enjuiciamiento Criminal, cuando no exista autor conocido de un delito, la Policía Judicial conservará el atestado a disposición del Ministerio Fiscal y de la Autoridad Judicial, sin enviárselo, salvo:',o:{a:'Que se trate de delitos contra la vida, integridad física, libertad e indemnidad sexuales, o de delitos relacionados con la corrupción.',b:'Que se practique cualquier diligencia después de transcurridas 72 horas desde la apertura del atestado o estas hayan tenido algún resultado.',c:'Que el Ministerio Fiscal o la Autoridad Judicial soliciten su remisión.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 284 LECrim establece todas estas excepciones: delitos graves específicos, diligencias tras 72h con resultado, y solicitud del MF o Autoridad Judicial.'}},
{n:31,q:'Según el artículo 284 de la Ley de Enjuiciamiento Criminal, la Policía Judicial comunicará al denunciante que, en caso de no ser identificado el autor en el plazo de setenta y dos horas,...',o:{a:'Las actuaciones se remitirán a la autoridad judicial, sin perjuicio de su derecho a reiterar la denuncia ante la fiscalía o el juzgado de instrucción.',b:'Las actuaciones no se remitirán, en ningún caso a la autoridad judicial.',c:'Las actuaciones no se remitirán a la autoridad judicial, salvo que se hubieran recogido armas, instrumentos o efectos de cualquier clase que puedan llevar a la detención del autor.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'El art. 284 LECrim establece que la PJ comunicará al denunciante que las actuaciones se remitirán a la autoridad judicial sin perjuicio de su derecho a reiterar la denuncia.'}},
{n:32,q:'Indique la respuesta que no es correcta. El artículo 284 de la LECrim establece que los funcionarios de la Policía Judicial extenderán una diligencia...',o:{a:'Expresiva del lugar, tiempo y ocasión en que se encontraren.',b:'En la que incluirán una descripción minuciosa para que se pueda formar idea cabal de los mismos y de las circunstancias de su hallazgo.',c:'Que solo en caso de extraordinaria y urgente necesidad podrá ser sustituida por un reportaje gráfico.',d:'Que será firmada por la persona en cuyo poder fueron hallados los efectos.'},correct:'c',why:{c:'El art. 284 LECrim no establece que la diligencia pueda ser sustituida por un reportaje gráfico. Esta opción es incorrecta.'}},
{n:33,q:'Con respecto a la incautación de efectos por la Policía Judicial, el artículo 284 de la LECrim establece que...',o:{a:'La incautación de efectos que pudieran pertenecer a una víctima del delito será comunicada a la misma.',b:'La persona afectada por la incautación de efectos procedentes de delitos podrá recurrir en cualquier momento la medida ante el juez de instrucción.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 284 LECrim establece que se comunicará la incautación a la víctima y que la persona afectada podrá recurrir la medida ante el juez de instrucción.'}},
{n:34,q:'El artículo 285 de la LECrim determina que si concurriere algún funcionario de Policía Judicial, de categoría superior a la del que estuviere actuando...',o:{a:'Este debe darle conocimiento de cuanto hubiese practicado, poniéndose a su disposición.',b:'Este dejará de actuar inmediatamente y no realizará actuación alguna hasta que reciba órdenes concretas.',c:'Este deberá seguir con la actuación salvo que el funcionario de categoría superior le indique lo contrario.',d:'Este cesará en sus actuaciones, entregará al funcionario superior todo lo actuado y abandonará el lugar.'},correct:'a',why:{a:'El art. 285 LECrim establece que el funcionario de inferior categoría dará conocimiento de cuanto hubiese practicado al superior, poniéndose a su disposición.'}},
{n:35,q:'Según el artículo 286 de la LECrim, cuando el Juez de Instrucción se presentare a formar el sumario, la autoridad o agente de policía, que estuviese practicando diligencias de prevención...',o:{a:'Le dará conocimiento de cuanto hubiese actuado, poniéndose a su disposición.',b:'Cesará en las diligencias y entregará a dicho juez las diligencias practicadas, los efectos relativos al delito y los detenidos, si los hubiere.',c:'Le comunicará lo actuado a ese momento, continuando con las diligencias a prevención, salvo que la autoridad judicial le ordenase actuar de otra manera.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'El art. 286 LECrim establece que cuando se presente el Juez de Instrucción, el agente de policía le dará conocimiento de cuanto hubiese actuado, poniéndose a su disposición.'}},
{n:36,q:'Según el artículo 287 de la LECrim, los funcionarios que constituyen la Policía Judicial...',o:{a:'Practicarán sin dilación, según sus atribuciones respectivas, las diligencias que los funcionarios del Ministerio Fiscal les encomienden para la comprobación del delito y averiguación de los delincuentes.',b:'Comunicarán a la autoridad o funcionario que le hubiere dado la queja la resolución que adopten, dejando constancia escrita en el atestado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 287 LECrim establece que los funcionarios de PJ practicarán sin dilación las diligencias que el MF les encomiende para la comprobación del delito y averiguación de los delincuentes.'}},
{n:37,q:'Según el artículo 287 de la LECrim, los funcionarios que constituyen la Policía Judicial...',o:{a:'No llevarán a cabo acto de investigación alguno sobre hechos que estén siendo objeto de instrucción por la autoridad judicial.',b:'Comunicarán el resultado de sus investigaciones al Ministerio Fiscal, adjuntando los efectos ocupados y los detenidos, quedando a la espera de lo que la Fiscalía pueda determinar.',c:'Practicarán sin dilación, según sus atribuciones respectivas, las diligencias que durante el curso de la causa les encarguen los jueces.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'c',why:{c:'El art. 287 LECrim establece que los funcionarios de PJ practicarán sin dilación las diligencias que durante el curso de la causa les encarguen los jueces.'}},
{n:38,q:'El funcionario de Policía Judicial que por cualquier causa no pueda cumplir el requerimiento o la orden que hubiese recibido del Ministerio Fiscal o Autoridad Judicial:',o:{a:'Lo pondrá inmediatamente en conocimiento del que haya hecho el requerimiento.',b:'Lo comunicará a su superior jerárquico para que éste se haga cargo de dicha orden.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El funcionario de PJ que no pueda cumplir el requerimiento lo pondrá inmediatamente en conocimiento de quien haya hecho el requerimiento.'}},
{n:39,q:'Según el artículo 770 de la LECrim, en el ámbito del procedimiento abreviado, la Policía Judicial tiene atribuida la facultad de:',o:{a:'Requerir la presencia de cualquier facultativo o personal sanitario para prestar los oportunos auxilios al ofendido.',b:'Recoger y custodiar los efectos, instrumentos o pruebas del delito de cuya desaparición hubiere peligro para ponerlos a disposición de la autoridad judicial.',c:'Tomar los datos personales y dirección de las personas que se encuentren en el lugar en que se cometió el hecho.',d:'Las respuestas a y b son correctas.'},correct:'d',why:{d:'El art. 770 LECrim atribuye a la PJ la facultad de requerir facultativos sanitarios y de recoger y custodiar efectos del delito, siendo correctas a y b.'}},
{n:40,q:'Según el artículo 770 de la LECrim, en el ámbito del procedimiento abreviado, la Policía Judicial tiene atribuida la facultad de:',o:{a:'Intervenir vehículos, sus permisos de circulación y los permisos de conducción de las personas a quienes se les impute un hecho punible.',b:'Efectuar ruedas de reconocimiento para la identificación de los responsables de hechos delictivos.',c:'Ordenar la práctica de intervenciones corporales sobre los detenidos con respecto a los principios de proporcionalidad y oportunidad.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 770 LECrim atribuye a la PJ la facultad de intervenir vehículos y permisos, efectuar ruedas de reconocimiento, y ordenar intervenciones corporales proporcionales.'}},
{n:41,q:'Según el artículo 770 de la LECrim, en el ámbito del procedimiento abreviado, la Policía Judicial tiene atribuida la facultad de:',o:{a:'Solicitar pruebas de exploración radiológica de los sospechosos para determinar sustancias en sangre u otros fluidos corporales.',b:'Retirar el cadáver de las vías públicas, trasladándolo al lugar que resulte más idóneo.',c:'En caso de delitos graves, llevar a cabo el registro de los lugares donde se sospeche que se ha producido la comisión del delito.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'d',why:{d:'Las opciones a, b y c no corresponden exactamente a facultades establecidas en el art. 770 LECrim tal como están redactadas.'}},
{n:42,q:'Según el artículo 770 de la LECrim, en el ámbito del procedimiento abreviado, la Policía Judicial tiene atribuida la facultad de:',o:{a:'Tomar nota de los teléfonos fijo o móvil de las personas que se encuentren en el lugar en que se cometió el hecho.',b:'Tomar nota del correo electrónico de las personas que se encuentren en el lugar en que se cometió el hecho.',c:'Tomar nota del número de fax de las personas que se encuentren en el lugar en que se cometió el hecho.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 770 LECrim permite a la PJ tomar nota de los teléfonos fijo o móvil, correo electrónico y demás datos de contacto de las personas presentes en el lugar del hecho.'}},
{n:43,q:'Según el artículo 771 de la LECrim, en el tiempo imprescindible y, en todo caso, durante el tiempo de la detención, la Policía Judicial...',o:{a:'Cumplirá con los deberes de información a las víctimas que prevé la legislación vigente.',b:'Informará al ofendido y al perjudicado por el delito, de forma escrita, de los derechos que les asisten de acuerdo con lo establecido en el artículo 520 de esta Ley.',c:'Informará al ofendido y al perjudicado de su derecho a la acción penal y a nombrar abogado.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 771 LECrim establece que la PJ cumplirá deberes de información a víctimas, informará de derechos según art. 520 y del derecho a nombrar abogado.'}},
{n:44,q:'Según el artículo 771 de la LECrim, en el tiempo imprescindible, la Policía Judicial...',o:{a:'Instruirá al ofendido y al perjudicado de su derecho a mostrarse parte en la causa, sin necesidad de formular querella.',b:'Informará al ofendido y al perjudicado que, de no personarse en la causa, y no hacer renuncia ni reserva de acciones civiles, el Ministerio Fiscal las ejercitará si correspondiere.',c:'Llevará a cabo una exhaustiva inspección ocular del lugar donde presumiblemente se haya cometido el delito.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 771 LECrim establece que la PJ instruirá al ofendido de su derecho a personarse, informará sobre acciones civiles del MF y llevará a cabo la inspección ocular.'}},
{n:45,q:'Según el artículo 771.2 de la LECrim, la Policía Judicial informará de la forma más comprensible al investigado no detenido. En particular, le instruirá de los derechos reconocidos en...',o:{a:'Los apartados a), b), c) y d) del artículo 520.2 de esta Ley.',b:'Los apartados a), b), e) del artículo 520.2 de esta Ley.',c:'Los apartados a), b), c) y f) del artículo 520.2 de esta Ley.',d:'Los apartados b), c), d) y e) del artículo 520.2 de esta Ley.'},correct:'a',why:{a:'El art. 771.2 LECrim establece que se instruirá al investigado no detenido de los derechos reconocidos en los apartados a), b), c) y d) del artículo 520.2.'}},
{n:46,q:'En aquellos delitos que solo pueden ser perseguidos a instancia de parte legítima, los funcionarios de la Policía Judicial:',o:{a:'Se abstendrán de intervenir.',b:'Tendrán las mismas obligaciones que si se tratara de delitos públicos, cuando se les requiera al efecto.',c:'Deberán practicar, como primera diligencia, la recepción de la denuncia de la víctima.',d:'No podrán intervenir sin autorización o requerimiento de la autoridad judicial.'},correct:'b',why:{b:'En los delitos solo perseguibles a instancia de parte, los funcionarios de PJ tendrán las mismas obligaciones que en delitos públicos cuando se les requiera al efecto.'}},
{n:47,q:'Los funcionarios de la Policía Judicial podrán dejar transcurrir más de 24 horas sin dar conocimiento a la autoridad judicial o Ministerio Fiscal de las diligencias que hubiesen practicado.',o:{a:'Solo cuando se trata de entrada y registro en lugares cerrados.',b:'Solo cuando se trata de delitos flagrantes.',c:'Solo cuando se trata de delitos cometidos por bandas organizadas.',d:'En ningún caso, salvo fuerza mayor.'},correct:'d',why:{d:'Los funcionarios de PJ no pueden dejar transcurrir más de 24 horas sin dar conocimiento a la autoridad judicial o MF, salvo fuerza mayor.'}},
{n:48,q:'Los funcionarios de Policía Judicial:',o:{a:'Están obligados a observar estrictamente las formalidades legales en cuantas diligencias practiquen.',b:'Se abstendrán, bajo su responsabilidad, de usar medios de averiguación que la ley no autorice.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'Los funcionarios de PJ están obligados a observar estrictamente las formalidades legales y a abstenerse de usar medios no autorizados por la ley, según el art. 297 LECrim.'}},
{n:49,q:'La regulación de la Policía Judicial en la Ley Orgánica 6/1985, del Poder Judicial, se contiene en...',o:{a:'El Título III de su Libro VII.',b:'El Título II de su Libro VII.',c:'El Título III de su Libro VIII.',d:'El Título II de su Libro VIII.'},correct:'b',why:{b:'La regulación de la PJ en la LOPJ se contiene en el Título II del Libro VII.'}},
{n:50,q:'La regulación de la Policía Judicial en la Ley Orgánica 6/1985, del Poder Judicial, se contiene en...',o:{a:'Los artículos 545 a 550.',b:'Los artículos 547 a 550.',c:'Los artículos 537 a 550.',d:'Los artículos 535 a 550.'},correct:'b',why:{b:'La regulación de la PJ en la LOPJ se contiene en los artículos 547 a 550.'}}
,{n:51,q:'El art.547 de la Ley Orgánica 6/1985, del Poder Judicial, determina que la función de Policía Judicial competería, cuando fueren requeridos a prestarla:',o:{a:'A todos los miembros de las Fuerzas y Cuerpos de Seguridad del Estado.',b:'A todos los miembros de las Fuerzas y Cuerpos de Seguridad dependientes de las Comunidades Autónomas.',c:'A todos los miembros de las Fuerzas y Cuerpos de Seguridad dependientes de las Corporaciones Locales.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 547 LOPJ establece que la función de PJ corresponde, cuando sean requeridos, a todos los miembros de las FFCCS del Estado, CCAA y Corporaciones Locales.'}}
,{n:52,q:'De acuerdo con lo previsto en el artículo 549 de la Ley Orgánica 6/1985, del Poder Judicial, corresponde específicamente a las Unidades Orgánicas de Policía Judicial la función de:',o:{a:'Averiguación de los responsables y circunstancias de los hechos delictivos, así como la detención de los primeros, dando cuenta seguidamente a la autoridad judicial y fiscal.',b:'El auxilio a la autoridad judicial y fiscal en cuantas actuaciones deba realizar fuera de su sede que requieran la presencia policial.',c:'La realización material de las actuaciones que exijan el ejercicio de la coerción y ordenare la autoridad judicial o fiscal.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 549 LOPJ establece que corresponde a las UO de PJ todas estas funciones: averiguación y detención, auxilio fuera de sede, y realización material de actuaciones coercitivas.'}}
,{n:53,q:'De acuerdo con lo previsto en el artículo 549 de la Ley Orgánica 6/1985, del Poder Judicial, corresponde específicamente a las Unidades Orgánicas de Policía Judicial la función de:',o:{a:'Garantizar el cumplimiento de las órdenes y resoluciones de la autoridad judicial o fiscal.',b:'La regulación del tráfico en vías interurbanas y la práctica de diligencias de prevención relacionadas con accidentes de tráfico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 549 LOPJ establece que corresponde a las UO de PJ garantizar el cumplimiento de las órdenes y resoluciones de la autoridad judicial o fiscal. La b no es función específica de PJ.'}}
,{n:54,q:'A los miembros de las Unidades Orgánicas de Policía Judicial se le podrán encomendar actuaciones, aunque no sean propias de la Policía Judicial:',o:{a:'Cuando así lo determine el Juzgado o Tribunal de quien dependan.',b:'Cuando así lo determine su superior jerárquico y siempre dentro del respeto a la Constitución y a la ley.',c:'En casos de catástrofe o calamidad pública.',d:'En ningún caso.'},correct:'b',why:{b:'A los miembros de las UO de PJ se les pueden encomendar actuaciones no propias de PJ cuando así lo determine su superior jerárquico, dentro del respeto a la CE y la ley.'}}
,{n:55,q:'Según el artículo 550 de la Ley Orgánica 6/1985, del Poder Judicial, los funcionarios de Policía Judicial, a quienes se hubiera encomendado una actuación o investigación concreta, dentro de sus competencias:',o:{a:'Deberán informar a su superior jerárquico regularmente de la marcha de la investigación, previa autorización del juez o tribunal del que dependan.',b:'No podrán ser removidos o apartados hasta que finalice la investigación, si no es por decisión o con autorización del juez o fiscal competente.',c:'No podrán ausentarse del Partido Judicial sin autorización del Juez o Tribunal que conozca la causa que están investigando.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'d',why:{d:'El art. 550 LOPJ establece condiciones diferentes a las descritas en a, b y c. Ninguna reproduce correctamente el texto del artículo.'}}
,{n:56,q:'Según el RD 769/1987, las funciones generales de Policía Judicial corresponderán:',o:{a:'Al Cuerpo de la Guardia Civil, en tiempos de paz.',b:'Al Cuerpo Nacional de Policía y Cuerpos de Policía de las Comunidades Autónomas.',c:'A los Cuerpos y Fuerzas de Seguridad del Estado, cualquiera que sea su naturaleza y dependencia.',d:'A todos los miembros de las Fuerzas y Cuerpos de Seguridad, cualquiera que sea su naturaleza y dependencia.'},correct:'d',why:{d:'El RD 769/1987 establece que las funciones generales de PJ corresponden a todos los miembros de las FFCCS, cualquiera que sea su naturaleza y dependencia.'}}
,{n:57,q:'Según el RD 769/1987, en defecto de Unidades Orgánicas de Policía Judicial, los Jueces, Tribunales y Fiscales podrán encomendar a las Fuerzas y Cuerpos de Seguridad la práctica de diligencias de investigación concretas...',o:{a:'De acuerdo con lo que reglamentariamente se determine.',b:'En caso de extraordinaria y urgente necesidad.',c:'Con carácter transitorio o en supuestos de urgencia.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El RD 769/1987 establece que en defecto de UO de PJ, Jueces, Tribunales y Fiscales pueden encomendar diligencias según reglamento, en urgencia o con carácter transitorio.'}}
,{n:58,q:'Según el RD 769/1987, los funcionarios policiales comisionados por la Autoridad Judicial o Fiscal para la práctica de alguna investigación concreta, se atendrán a las órdenes y directrices que hubiesen recibido...',o:{a:'Dando conocimiento de ello a su superior jerárquico.',b:'Sin perjuicio de las órdenes que hubiesen recibido de su superior jerárquico cuando se trate de actuaciones administrativas.',c:'Sin que las instrucciones de carácter técnico que obtuvieren de sus superiores policiales inmediatos puedan contradecirlas.',d:'Ateniéndose a las instrucciones de carácter técnico de sus superiores policiales, quienes podrán asumir la dirección de dicha investigación.'},correct:'c',why:{c:'Los funcionarios comisionados se atendrán a las órdenes de la autoridad judicial sin que las instrucciones técnicas de sus superiores policiales inmediatos puedan contradecirlas.'}}
,{n:59,q:'Según el RD 769/1987, los funcionarios de las Unidades Orgánicas de Policía Judicial actuarán bajo la dependencia del Ministerio Fiscal cuando realicen diligencias de investigación criminal, formalmente concretadas a un supuesto presuntamente delictivo:',o:{a:'Con carácter previo a la apertura de la correspondiente actuación judicial.',b:'Por delegación de la autoridad judicial.',c:'Cuando la autoridad judicial hubiese sobreseído el expediente de manera provisional por falta de pruebas.',d:'Una vez finalizada la instrucción del procedimiento, siempre que no haya tenido lugar el juicio oral.'},correct:'a',why:{a:'Los funcionarios de las UO de PJ actúan bajo dependencia del MF cuando realizan diligencias de investigación criminal con carácter previo a la apertura de actuación judicial.'}}
,{n:60,q:'Según el RD 769/1987, las Unidades de Policía Judicial, especialmente adscritas a órganos jurisdiccionales o Fiscalías, deberán, siempre que sea posible, tener su sede:',o:{a:'En la Subdelegación del Gobierno de la provincia.',b:'En las Comisarías Centrales del Cuerpo Nacional de Policía.',c:'En las propias dependencias de edificios judiciales o fiscales.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'c',why:{c:'El RD 769/1987 establece que las Unidades de PJ adscritas a órganos jurisdiccionales o Fiscalías deberán tener su sede en las propias dependencias de edificios judiciales o fiscales.'}}
,{n:61,q:'Según el RD 769/1987, la función de coordinación general de las Unidades de Policía Judicial adscritas a órganos jurisdiccionales o Fiscalías corresponde:',o:{a:'Al Subdelegado del Gobierno en la provincia.',b:'A los respectivos Decanatos.',c:'Al Delegado del Gobierno en la Comunidad Autónoma.',d:'Al Fiscal General del Estado.'},correct:'d',why:{d:'El RD 769/1987 establece que la función de coordinación general de las UO de PJ adscritas a órganos jurisdiccionales o Fiscalías corresponde al Fiscal General del Estado.'}}
,{n:62,q:'Según el RD 769/1987, las Unidades de Policía Judicial especialmente adscritas a órganos jurisdiccionales o Fiscalías se compondrán:',o:{a:'Únicamente de funcionarios diplomados y especializados en Policía Judicial, que hayan superado los cursos previstos.',b:'De funcionarios diplomados en Policía Judicial y de otros efectivos policiales no necesariamente dotados de formación especializada en esta materia.',c:'De funcionarios diplomados en Policía Judicial y de médicos forenses.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'El RD 769/1987 establece que las UO de PJ adscritas se compondrán únicamente de funcionarios diplomados y especializados que hayan superado los cursos previstos.'}}
,{n:63,q:'Según el artículo 28 del Real Decreto 769/1987, son funciones de las Unidades de Policía Judicial, especialmente adscritas a órganos jurisdiccionales o Fiscalías:',o:{a:'La realización de inspecciones oculares y recogida de pruebas.',b:'La anotación de primeros datos, averiguación de domicilios y paraderos y emisiones de informes de solvencia o conducta.',c:'La emisión, incluso verbal, de informes periciales provisionales, pero de urgente necesidad para adoptar decisiones judiciales que no admitan dilación.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 28 RD 769/1987 establece todas estas funciones: inspecciones oculares, anotación de datos, y emisión de informes periciales urgentes.'}}
,{n:64,q:'Según el artículo 28 del Real Decreto 769/1987, son funciones de las Unidades de Policía Judicial, especialmente adscritas a órganos jurisdiccionales o Fiscalías:',o:{a:'La intervención técnica en el levantamiento de cadáveres.',b:'Las actuaciones de inmediata intervención.',c:'La ejecución de órdenes inmediatas de Presidentes, Jueces y Fiscales.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 28 RD 769/1987 incluye: intervención técnica en levantamiento de cadáveres, actuaciones de inmediata intervención y ejecución de órdenes de Jueces y Fiscales.'}}
,{n:65,q:'Según el RD 769/1987, y con respecto a los miembros de las Unidades Orgánicas de Policía Judicial, indique la afirmación incorrecta:',o:{a:'Deberán rendir cumplida cuenta de la evolución y resultado final de sus actuaciones al Juez o Fiscal que las hubiese ordenado.',b:'Deberán ser diplomados y especializados en Policía Judicial y haber superado los cursos de selección previstos en el Capítulo VII del RD 769/1987.',c:'Tendrán la consideración de comisionados en las diligencias que les encargaren la autoridad judicial o Fiscal.',d:'Deberán guardar rigurosa reserva sobre lo investigado, aunque ello no impedirá, salvo prohibición expresa, el intercambio de información, dentro de la propia unidad.'},correct:'c',why:{c:'La consideración de comisionados se aplica a los funcionarios comisionados por la autoridad judicial, no a los miembros de las UO de PJ en general. La opción c es incorrecta.'}}
,{n:66,q:'Con la finalidad de armonizar y lograr la unidad de dirección en las fuerzas policiales adscritas a la investigación criminal, el RD. 769/1987 dispone la creación de...',o:{a:'Una Comisión Nacional de Policía Judicial.',b:'Comisiones Provinciales de Policía Judicial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El RD 769/1987 dispone la creación tanto de una Comisión Nacional de PJ como de Comisiones Provinciales de PJ.'}}
,{n:67,q:'No forma parte de la Comisión Nacional de Policía Judicial:',o:{a:'El Presidente del Tribunal Supremo.',b:'El Presidente de la Audiencia Nacional.',c:'El Ministro de Justicia.',d:'El Ministro de Interior.'},correct:'d',why:{d:'El Ministro de Interior no forma parte de la Comisión Nacional de PJ. Forman parte el Presidente del TS, el de la AN, el Ministro de Justicia y el FGE, entre otros.'}}
,{n:68,q:'No forma parte de la Comisión Nacional de Policía Judicial:',o:{a:'El Presidente de la Asociación Profesional de la Magistratura.',b:'Un magistrado nombrado por el Consejo General del Poder Judicial.',c:'Un vocal del Consejo General del Poder Judicial.',d:'El Secretario de Estado para la Seguridad.'},correct:'a',why:{a:'El Presidente de la Asociación Profesional de la Magistratura no forma parte de la Comisión Nacional de PJ. Es un órgano institucional, no de representación profesional.'}}
,{n:69,q:'Forma parte de la Comisión Nacional de Policía Judicial:',o:{a:'El Fiscal General del Estado.',b:'El Presidente del Consejo General del Poder Judicial.',c:'Un representante de cada una de las Comunidades Autónomas con competencia estatutaria que ejerzan efectivamente funciones de policía judicial.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'Forman parte de la Comisión Nacional de PJ el FGE, el Presidente del CGPJ y un representante de cada CCAA con competencia en seguridad que ejerza funciones de PJ.'}}
,{n:70,q:'No forma parte de las Comisiones Provinciales de Policía Judicial:',o:{a:'El Jefe de Policía Local del ayuntamiento donde radique la sede de la Unidad Orgánica de Policía Judicial.',b:'El Jefe de la Unidad Orgánica de Policía Judicial de la Guardia Civil.',c:'El Jefe de la Unidad Orgánica de Policía Judicial del Cuerpo Nacional de Policía.',d:'El Magistrado Juez Decano de los Juzgados de primera Instancia e Instrucción de la capital de la provincia.'},correct:'a',why:{a:'El Jefe de Policía Local no forma parte de las Comisiones Provinciales de PJ. Estas se componen de representantes de la autoridad judicial, MF y las UO de PJ del CNP y GC.'}}
,{n:71,q:'No forma parte de las Comisiones Provinciales de Policía Judicial:',o:{a:'El Presidente de la Audiencia Provincial.',b:'Un funcionario de Policía Judicial designado por los sindicatos más representativos en la provincia.',c:'El Fiscal Jefe de la Audiencia Provincial.',d:'El Magistrado Juez Decano de los Juzgados de primera Instancia e Instrucción de la capital de la provincia.'},correct:'b',why:{b:'Los sindicatos no designan representantes en las Comisiones Provinciales de PJ. Esta opción es incorrecta.'}}
,{n:72,q:'En materia de Policía Judicial, el artículo 29.2. de la Ley Orgánica 2/1986, de Fuerzas y Cuerpos de Seguridad, establece que el personal de las Policías Locales...',o:{a:'Tendrá carácter colaborador de las Fuerzas y Cuerpos de Seguridad del Estado.',b:'Podrá ser comisionado para la realización de diligencias fuera de su término municipal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 29.2 LO 2/1986 establece que el personal de las Policías Locales tendrá carácter colaborador de las FFCCS del Estado en materia de PJ.'}}
,{n:73,q:'Con respecto a las funciones de la Policía Local como policía judicial, indique la afirmación incorrecta:',o:{a:'Los miembros de la Policía Local forman parte de la policía judicial en sentido genérico.',b:'Los miembros de la Policía Local podrán formar parte de las Unidades Orgánicas de Policía Judicial, conforme a lo dispuesto en los artículos 29 y 53 de la Ley Orgánica 2/1986.',c:'Los miembros de la Policía Local deben efectuar diligencias de prevención y cuantas actuaciones tiendan a evitar la comisión de actos delictivos en el marco de colaboración establecido en las Juntas Locales de Seguridad.',d:'La instrucción de atestados por accidentes de circulación dentro del casco urbano es competencia atribuida a la Policía Local.'},correct:'b',why:{b:'Los miembros de la PL no pueden formar parte de las UO de PJ. El art. 29 LO 2/1986 les atribuye solo carácter colaborador. La opción b es incorrecta.'}}
,{n:74,q:'En la Ley de Enjuiciamiento Criminal, el enunciado "De la comprobación del delito y averiguación del delincuente"...',o:{a:'Es el Título VI de su Libro II.',b:'Es el Título V de su Libro II.',c:'Es el Título V de su Libro I.',d:'Es el Título VI de su Libro I.'},correct:'b',why:{b:'En la LECrim, el enunciado "De la comprobación del delito y averiguación del delincuente" corresponde al Título V del Libro II.'}}
,{n:75,q:'En la Ley de Enjuiciamiento Criminal, el enunciado "De la comprobación del delito y averiguación del delincuente"...',o:{a:'Comprende los artículos 426 a 485.',b:'Comprende los artículos 326 a 385.',c:'Comprende los artículos 326 a 485.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'b',why:{b:'El Título V del Libro II de la LECrim, sobre comprobación del delito y averiguación del delincuente, comprende los artículos 326 a 385.'}}
,{n:76,q:'En la Ley de Enjuiciamiento Criminal, dentro del Título V de su Libro II, "De la comprobación del delito y averiguación del delincuente" se contiene...',o:{a:'El capítulo I dedicado a la inspección ocular.',b:'El capítulo II dedicado a la destrucción y realización anticipada de los efectos judiciales.',c:'El capítulo IV dedicado a la identidad del delincuente y sus circunstancias personales.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El Título V Libro II LECrim contiene el capítulo I de inspección ocular, el II de destrucción y realización anticipada de efectos, y el IV de identidad del delincuente.'}}
,{n:77,q:'En la Ley de Enjuiciamiento Criminal, dentro del Título V de su Libro II, "De la comprobación del delito y averiguación del delincuente" se contiene...',o:{a:'El capítulo II dedicado a las declaraciones de los procesados.',b:'El capítulo III dedicado a las declaraciones de los testigos.',c:'El capítulo IV dedicado al cuerpo del delito.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'d',why:{d:'El Título V Libro II LECrim no contiene capítulos dedicados a declaraciones de procesados o testigos en esa numeración. Ninguna es correcta.'}}
,{n:78,q:'En la Ley de Enjuiciamiento Criminal, dentro del Título V de su Libro II, "De la comprobación del delito y averiguación del delincuente" se contiene...',o:{a:'El capítulo II dedicado al cuerpo del delito.',b:'El capítulo II Bis dedicado a la destrucción y realización anticipada de los efectos judiciales.',c:'El capítulo V dedicado a las declaraciones de los testigos.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El Título V Libro II LECrim contiene el cap. II sobre el cuerpo del delito, el cap. II Bis sobre destrucción anticipada, y el cap. V sobre declaraciones de testigos.'}}
,{n:79,q:'En la Ley de Enjuiciamiento Criminal, dentro del Título V de su Libro II, "De la comprobación del delito y averiguación del delincuente" se contiene...',o:{a:'El capítulo V dedicado al careo de los testigos y procesados.',b:'El capítulo VII dedicado al informe pericial.',c:'El capítulo VI dedicado a la citación, detención y prisión provisional.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El Título V Libro II LECrim contiene el cap. V sobre careo de testigos y procesados, el cap. VII sobre informe pericial, y el cap. VI sobre citación, detención y prisión provisional.'}}
,{n:80,q:'De acuerdo con lo previsto en el artículo 334 de la LECrim, con respecto al cuerpo del delito, el juez instructor:',o:{a:'Ordenará recoger en los primeros momentos las armas e instrumentos o efectos de cualquier clase que puedan tener relación con el delito y se hallen en el lugar en que este se cometió.',b:'Extenderá diligencia expresiva del lugar, tiempo y ocasión del hallazgo de armas e instrumentos, describiéndolos minuciosamente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 334 LECrim establece que el juez instructor ordenará recoger los efectos del delito y se extenderá diligencia expresiva del hallazgo.'}}
,{n:81,q:'El artículo 334 de la LECrim dispone que se extenderá diligencia expresiva del lugar, tiempo y ocasión en que se encontraren las armas, instrumentos o efectos. El encargado de extender esta diligencia es el:',o:{a:'Juez Instructor.',b:'Letrado de la Administración de Justicia.',c:'Fiscal encargado de la instrucción de la causa.',d:'Jefe de la Unidad Orgánica de Policía Judicial.'},correct:'b',why:{b:'Según el art. 334 LECrim, el encargado de extender la diligencia expresiva del hallazgo es el Letrado de la Administración de Justicia.'}}
,{n:82,q:'Respecto al cuerpo del delito, el artículo 334 de la LECrim dispone que:',o:{a:'Los efectos que pertenecieren a la víctima del delito serán restituidos inmediatamente a la misma, salvo que excepcionalmente debieran ser conservados como medio de prueba.',b:'Los efectos serán restituidos inmediatamente cuando deban ser conservados como medio de prueba, pero su conservación pueda garantizarse imponiendo al propietario el deber de mantenerlos a disposición del Juez o Tribunal.',c:'La víctima podrá recurrir la medida de no restitución de los efectos del delito que le pertenezcan ante el Juez de Instrucción, sin necesidad de abogado.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 334 LECrim establece todas estas disposiciones: restitución a la víctima con excepciones, conservación imponiéndola al propietario, y posibilidad de recurrir sin abogado.'}}
,{n:83,q:'De acuerdo con lo previsto en el artículo 335 de la LECrim, cuando durante la fase de instrucción, el juez hallare la persona o cosa objeto del delito:',o:{a:'Describirá detalladamente su estado y circunstancias y especialmente todas las que tuviesen relación con el hecho punible.',b:'Ordenará su inmediato aseguramiento, adoptando medidas cautelares que incluso pueden llegar a la privación de libertad y al embargo de bienes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 335 LECrim establece que el juez describirá detalladamente el estado y circunstancias del objeto del delito y ordenará su inmediato aseguramiento con medidas cautelares.'}}
,{n:84,q:'De acuerdo con el artículo 335 de la LECrim, en un delito de falsificación cometido en documentos existentes en dependencias de administraciones públicas, si el juez instructor los considerase imprescindibles para el reconocimiento pericial:',o:{a:'El Juez instructor los reclamará y los mantendrá en su poder hasta que finalice la causa.',b:'El Letrado de la Administración de Justicia los reclamará a las correspondientes autoridades, sin perjuicio de devolverlos después de finalizada la causa.',c:'El Juez instructor ordenará a las correspondientes autoridades que le remitan copias autenticadas, sin perjuicio de devolverlos cuando finalice la causa.',d:'El Secretario Judicial ordenará a la Policía Judicial el registro de las dependencias oficiales donde tales documentos se encuentren.'},correct:'c',why:{c:'El art. 335 LECrim establece que el juez ordenará a las autoridades que le remitan copias autenticadas, sin perjuicio de devolverlos cuando finalice la causa.'}}
,{n:85,q:'De acuerdo con el artículo 337 de la LECrim, cuando en el acto de describir las personas o cosas objeto del delito estuvieren presentes personas que puedan declarar sobre el modo en que el delito se hubiese cometido:',o:{a:'Serán examinadas antes de la descripción y sus declaraciones se considerarán complemento de ésta.',b:'Serán examinadas después de la descripción y sus declaraciones se considerarán complemento de ésta.',c:'Serán examinadas antes de la descripción y sus declaraciones se remitirán al Ministerio Fiscal en pieza separada.',d:'Serán examinadas después de la descripción y sus declaraciones se remitirán al Ministerio Fiscal en pieza separada.'},correct:'a',why:{a:'El art. 337 LECrim establece que las personas serán examinadas antes de la descripción y sus declaraciones se considerarán complemento de ésta.'}}
,{n:86,q:'De acuerdo con el artículo 338 de la LECrim, en lo que respecta a los instrumentos, armas y efectos del delito hallados durante la instrucción del sumario:',o:{a:'Se recogerán de tal forma que se garantice su integridad.',b:'El Letrado de la Administración de Justicia acordará su retención, conservación y envío al organismo adecuado para su depósito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 338 LECrim establece que los efectos se recogerán garantizando su integridad y el LAJ acordará su retención, conservación y envío al organismo de depósito.'}}
,{n:87,q:'De acuerdo con el artículo 340 de la LECrim, si la instrucción de un delito tuviere lugar por causa de muerte violenta o sospechosa de criminalidad, el cadáver se identificará por medio de testigos:',o:{a:'Antes de proceder a su enterramiento.',b:'Después de su exhumación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 340 LECrim establece que el cadáver se identificará por medio de testigos antes de proceder a su enterramiento.'}}
,{n:88,q:'De acuerdo con el artículo 341 de la LECrim, cuando un cadáver no pueda ser identificado por medio de testigos y su estado lo permita:',o:{a:'Se expondrá al público antes de practicar la autopsia.',b:'Se expondrá al público después de practicada la autopsia.',c:'Será embalsamado y expuesto al público.',d:'Será enterrado, previa la obtención de fotografías del mismo.'},correct:'a',why:{a:'El art. 341 LECrim establece que cuando el cadáver no pueda ser identificado por testigos y su estado lo permita, se expondrá al público antes de practicar la autopsia.'}}
,{n:89,q:'De acuerdo con el artículo 341 de la LECrim, cuando un cadáver no pueda ser identificado por medio de testigos y su estado no lo permita, se expondrá al público antes de practicar la autopsia:',o:{a:'Por un tiempo mínimo de 24 horas.',b:'Por un tiempo máximo de 24 horas.',c:'Por el tiempo que las circunstancias aconsejen.',d:'Por el tiempo imprescindible para lograr la identificación requerida.'},correct:'d',why:{d:'El art. 341 LECrim establece que cuando el estado del cadáver no permita la exposición directa, se expondrá por el tiempo imprescindible para lograr la identificación requerida.'}}
,{n:90,q:'Según el art. 341 de la LECrim, cuando un cadáver no pueda ser identificado por testigos y su estado lo permita, se expondrá al público por un tiempo mínimo de 24 horas, expresando en un cartel fijado a la puerta del depósito:',o:{a:'El sitio, hora y día en que aquél se hubiese hallado.',b:'El Juez que estuviese instruyendo el sumario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 341 LECrim establece que el cartel expresará el sitio, hora y día del hallazgo y el Juez que instruye el sumario.'}}
,{n:91,q:'De acuerdo con el artículo 342 de la LECrim, cuando a pesar de la exposición pública de un cadáver éste no fuere reconocido, el juez instructor:',o:{a:'Ordenará que se recojan todos los efectos personales con los que se hubiere encontrado, a fin de que puedan servir para la identificación.',b:'Recogerá todas las prendas con que se le hubiera encontrado, a fin de que puedan servir para su identificación.',c:'Ordenará la inserción de fotografías en todos los medios de comunicación públicos de su jurisdicción.',d:'Ordenará al Letrado de la Administración de Justicia que se recojan todos los efectos personales.'},correct:'a',why:{a:'El art. 342 LECrim establece que el juez instructor ordenará que se recojan todos los efectos personales con los que se hubiere encontrado el cadáver para su identificación.'}}
,{n:92,q:'Según los artículos 344 a 349 de la LECrim, y con respecto al médico forense, indique la respuesta que no es correcta:',o:{a:'Está obligado a practicar todo acto o diligencia propios de su profesión con el celo, esmero y prontitud que la naturaleza del caso exija.',b:'Residirá en la capital del Juzgado para el que haya sido nombrado, y no podrá ausentarse de ella sin licencia del Juez, cuando la duración no exceda de ocho días.',c:'Cuando el Juez estimase necesaria la cooperación de más facultativos, hará el oportuno nombramiento, una vez oído al médico forense titular.',d:'Es el facultativo encargado de auxiliar a la administración de justicia, en todos los casos y actuaciones en los que sea necesaria su intervención.'},correct:'b',why:{b:'El médico forense no está obligado a residir en la capital del juzgado con esas condiciones. La opción b no refleja correctamente lo establecido en los arts. 344-349 LECrim.'}}
,{n:93,q:'De acuerdo con el artículo 350 de la LECrim, en los casos de envenenamiento, heridas u otras lesiones, el médico forense quedará encargado de la asistencia facultativa al paciente:',o:{a:'A no ser que éste o su familia prefieran la de uno o más profesionales de su elección, en cuyo caso al forense solo le corresponde la inspección y vigilancia de su evolución.',b:'A no ser que el juez, mediante resolución motivada, decida que otro facultativo realice tales labores.',c:'A no ser que el médico forense delegue en otro facultativo, dando cuenta inmediata al juez instructor.',d:'Salvo en aquellos casos que precisen de una atención más especializada.'},correct:'a',why:{a:'El art. 350 LECrim establece que el médico forense asistirá al paciente a no ser que éste o su familia prefieran la de uno o más profesionales de su elección.'}}
,{n:94,q:'De acuerdo con el artículo 353 de la LECrim, las autopsias:',o:{a:'Se harán en el local público que la Administración tenga destinado para depósito de cadáveres.',b:'Podrán realizarse en el domicilio del difunto, si la familia lo pidiere, el juez de instrucción lo autorizare y no se perjudicase el éxito del sumario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 353 LECrim establece que las autopsias se harán en local público pero pueden realizarse en el domicilio del difunto si la familia lo pide y el juez lo autoriza.'}}
,{n:95,q:'De acuerdo con el artículo 353 de la LECrim, si el Juez de instrucción no pudiere asistir a la autopsia:',o:{a:'Delegará en el Letrado de la Administración de Justicia.',b:'Delegará en un funcionario de policía judicial, dando fe de su asistencia, así como de lo que en aquella ocurriere, el Letrado de la Administración de Justicia de la causa.',c:'Delegará en un funcionario de policía judicial o en el Letrado de la Administración de Justicia de la causa.',d:'Delegará en un funcionario del Ministerio Fiscal, funcionario de la Policía Judicial o Letrado de la Administración de Justicia de la causa.'},correct:'b',why:{b:'El art. 353 LECrim establece que si el juez no puede asistir delegará en un funcionario de policía judicial, dando fe el LAJ de su asistencia y de lo ocurrido.'}}
,{n:96,q:'De acuerdo con el artículo 354 de la LECrim, cuando sobreviniere la muerte de una persona como consecuencia de accidente ocurrido en vía férrea, yendo un tren en marcha:',o:{a:'El juez instructor ordenará la inmediata retirada del tren a un lugar de la estación más próxima.',b:'El tren únicamente se detendrá el tiempo preciso para separar el cadáver de la vía.',c:'El tren continuará su marcha tan pronto como quede expedita la vía.',d:'El tren y su conductor quedarán a disposición de los funcionarios de policía judicial encargados de la investigación, por el tiempo imprescindible, sin perjuicio de la adopción de las medidas necesarias para el traslado de los pasajeros.'},correct:'d',why:{d:'El art. 354 LECrim establece que el tren y su conductor quedarán a disposición de los funcionarios de PJ por el tiempo imprescindible, sin perjuicio del traslado de pasajeros.'}}
,{n:97,q:'El artículo 356 de la LECrim dispone que las operaciones de análisis químico que exijan la sustanciación de los procesos criminales, se practicarán por:',o:{a:'Doctores en medicina, en Farmacia, en Ciencias Físico Químicas, o por Ingenieros que se hayan dedicado a la especialidad química.',b:'El médico forense o su sustituto legal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 356 LECrim dispone que los análisis químicos en procesos criminales se practicarán por Doctores en medicina, Farmacia, Ciencias Físico Químicas o Ingenieros especializados en química.'}}
,{n:98,q:'De acuerdo con el artículo 363 de la LECrim, los juzgados y tribunales ordenarán la práctica de análisis químicos:',o:{a:'En aquellos casos de muerte por envenenamiento en los que no se haya podido determinar la sustancia causante.',b:'Únicamente en los casos en los que se consideren absolutamente indispensables para la necesaria investigación judicial y la recta administración de justicia.',c:'En todos los casos de muerte violenta o sospechosa de criminalidad.',d:'En aquellos casos de muerte por envenenamiento o por inhalación de sustancias capaces de producir la muerte.'},correct:'b',why:{b:'El art. 363 LECrim establece que los juzgados ordenarán análisis químicos únicamente cuando se consideren absolutamente indispensables para la investigación judicial y la recta administración de justicia.'}}
,{n:99,q:'De acuerdo con el artículo 363 de la LECrim, el Juez de Instrucción podrá acordar la obtención de muestras biológicas del sospechoso que resulten indispensables para la determinación de su perfil de ADN:',o:{a:'Siempre que concurran acreditadas razones que lo justifiquen.',b:'Mediante resolución motivada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 363 LECrim establece que el Juez de Instrucción podrá acordar la obtención de muestras biológicas siempre que concurran razones acreditadas y mediante resolución motivada.'}}
,{n:100,q:'El Juez de Instrucción podrá acordar la obtención de muestras biológicas para la determinación del perfil de ADN, pudiendo decidir a tal fin la práctica de aquellos actos de inspección, reconocimiento o intervención corporal adecuados a los principios de:',o:{a:'Proporcionalidad y congruencia.',b:'Proporcionalidad y razonabilidad.',c:'Razonabilidad y congruencia.',d:'Oportunidad, proporcionalidad y congruencia.'},correct:'a',why:{a:'El art. 363 LECrim establece que los actos de intervención corporal para obtención de muestras de ADN deben respetar los principios de proporcionalidad y congruencia.'}}
,{n:101,q:'La toma de muestras biológicas y la realización de análisis para la obtención de identificadores de ADN e inscripción de los mismos en la base de datos policial, podrá acordarse:',o:{a:'Cuando se trate de condenados por la comisión de un delito grave contra la vida, la integridad de las personas, la libertad o indemnidad sexual, o de terrorismo.',b:'Cuando se trate de condenados por cualquier delito grave que conlleve un riesgo grave para la vida, la salud o la integridad física de las personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'La toma de muestras de ADN puede acordarse tanto para condenados por delitos graves contra la vida/integridad/libertad sexual/terrorismo como por delitos graves con riesgo para la vida o integridad.'}}
,{n:102,q:'Con respecto a la toma de muestras biológicas de un sospechoso para la obtención de identificadores de ADN, indique la afirmación correcta:',o:{a:'Podrán acordarse cuando de las circunstancias del hecho, antecedentes o valoración de su personalidad pueda valorarse que existe un peligro relevante de reiteración delictiva.',b:'Únicamente podrán llevarse a cabo los análisis necesarios para obtener los identificadores que proporcionen, exclusivamente, información genética reveladora de la identidad de la persona y de su sexo.',c:'Si el afectado se opusiera a la recogida de las muestras, podrá imponerse su ejecución forzosa mediante el recurso a las medidas coactivas mínimas indispensables.',d:'Todas las afirmaciones descritas son correctas.'},correct:'d',why:{d:'Todas las afirmaciones son correctas respecto a la toma de muestras biológicas: criterio de peligro de reiteración, limitación a datos de identidad y sexo, y posibilidad de ejecución forzosa proporcional.'}}
,{n:103,q:'La toma de muestras biológicas de un sospechoso y la realización de análisis para la obtención de identificadores de ADN deberán ser en todo caso:',o:{a:'Proporcionadas a las circunstancias del caso.',b:'Respetuosas con su dignidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'La toma de muestras biológicas debe ser en todo caso proporcionada a las circunstancias y respetuosa con la dignidad del afectado.'}}
,{n:104,q:'En los delitos de robo, hurto, estafa y en cualesquiera otros en que deba hacerse constar la preexistencia de las cosas robadas, si no hubiese testigos presenciales del hecho:',o:{a:'Se recibirá información sobre los antecedentes del que se presentare como agraviado.',b:'Se recibirá información sobre todas las circunstancias que ofrecieren indicios de hallarse el agraviado poseyendo aquellos al tiempo en que resulte cometido el delito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 364 LECrim establece que se recibirá información sobre los antecedentes del agraviado y sobre las circunstancias que acrediten la preexistencia de los efectos robados.'}}
,{n:105,q:'De acuerdo con el artículo 365 de la LECrim, cuando para la calificación del delito fuere necesario estimar el valor de la cosa que hubiese sido su objeto, o el importe del perjuicio causado, el juez instructor:',o:{a:'Interesará un informe económico y de mercado.',b:'Primero oirá al dueño o perjudicado y posteriormente acordará el reconocimiento pericial.',c:'Reclamará la factura de compra.',d:'Primero acordará el reconocimiento pericial y posteriormente oirá al dueño o perjudicado.'},correct:'b',why:{b:'El art. 365 LECrim establece que primero se oirá al dueño o perjudicado y posteriormente se acordará el reconocimiento pericial.'}}
,{n:106,q:'De acuerdo con el artículo 365 de la LECrim, la valoración de las mercancías sustraídas en establecimientos comerciales se fijará:',o:{a:'Tal y como se determine en el reconocimiento pericial.',b:'Atendiendo a su precio de venta al público.',c:'Conforme a su valor de compra por el comerciante.',d:'Según los criterios de libre mercado.'},correct:'b',why:{b:'El art. 365 LECrim establece que la valoración de mercancías sustraídas en establecimientos comerciales se fijará atendiendo a su precio de venta al público.'}}
,{n:107,q:'De acuerdo con el artículo 367 bis de la LECrim, tendrán la consideración de efectos judiciales en el orden penal:',o:{a:'Todos los bienes embargados puestos a disposición judicial en el curso de un procedimiento penal.',b:'Todos los bienes incautados, puestos a disposición judicial en el curso de un procedimiento penal.',c:'Todos los bienes aprehendidos, puestos a disposición judicial en el curso de un procedimiento penal.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 367 bis LECrim establece que tendrán consideración de efectos judiciales los bienes embargados, incautados y aprehendidos puestos a disposición judicial.'}}
,{n:108,q:'De acuerdo con el artículo 367 ter de la LECrim, podrá decretarse la destrucción de los efectos intervenidos judicialmente:',o:{a:'Cuando resulte necesario o conveniente por la propia naturaleza de los efectos, dando audiencia al MF y al propietario, dejando muestras suficientes.',b:'Cuando su almacenamiento o custodia supongan un peligro real o potencial, dando audiencia al MF y al propietario, dejando muestras suficientes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 367 ter LECrim permite la destrucción de efectos tanto cuando sea necesario por su naturaleza como cuando su custodia suponga peligro, siempre con audiencia y dejando muestras.'}}
,{n:109,q:'De acuerdo con el artículo 367 ter de la LECrim, en el supuesto de que los efectos puestos a disposición de la autoridad judicial consistan en drogas tóxicas, estupefacientes o sustancias psicotrópicas:',o:{a:'El juez instructor ordenará su inmediata destrucción dejando muestras suficientes para garantizar ulteriores comprobaciones o investigaciones.',b:'Antes de su destrucción, el Juez instructor dará audiencia al Ministerio Fiscal y a las partes.',c:'El juez instructor puede, de forma motivada, acordar que se conserven la totalidad de estas sustancias.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 367 ter LECrim establece que en el caso de drogas el juez ordenará la destrucción dejando muestras, dará audiencia al MF y partes, y puede acordar conservar la totalidad de forma motivada.'}}
,{n:110,q:'Conforme al artículo 367 ter de la LECrim, en el supuesto de que los efectos puestos a disposición de la autoridad judicial consistan en drogas tóxicas, el encargado de custodiar estas sustancias es:',o:{a:'El propio juez de instrucción.',b:'El Letrado de la Administración de Justicia.',c:'La Policía Judicial.',d:'El Ministerio Fiscal.'},correct:'c',why:{c:'Conforme al art. 367 ter LECrim, la custodia de las drogas tóxicas y estupefacientes puestas a disposición judicial corresponde a la Policía Judicial.'}}
,{n:111,q:'La destrucción anticipada de efectos judiciales prevista en el artículo 367 ter de la LECrim es aplicable cuando se trate de:',o:{a:'Drogas tóxicas, sustancias estupefacientes o psicotrópicas.',b:'Efectos relacionados con la comisión de delitos contra la propiedad intelectual.',c:'Efectos relacionados con la comisión de delitos contra la propiedad industrial.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 367 ter LECrim aplica la destrucción anticipada a drogas y estupefacientes, y también a efectos relacionados con delitos contra la propiedad intelectual e industrial.'}}
,{n:112,q:'De acuerdo con el artículo 367 ter de la LECrim, cuando durante la instrucción el juez instructor ordene la destrucción de los efectos intervenidos:',o:{a:'Se extenderá la oportuna diligencia.',b:'Deberá quedar constancia en autos de la naturaleza, calidad, cantidad, peso y medida de los efectos destruidos.',c:'Si no hubiere tasación, se dejará constancia de su valor, si su fijación fuere imposible después de la destrucción.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 367 ter LECrim establece que al destruir efectos intervenidos se extenderá diligencia, constará la naturaleza y cantidad de lo destruido, y si no hay tasación se dejará constancia del valor posible.'}}
,{n:113,q:'De acuerdo con el artículo 367 ter de la LECrim, cuando los objetos o efectos intervenidos por el juez instructor no pudieren, por su naturaleza, conservarse en su forma primitiva:',o:{a:'El juez resolverá lo que estime conveniente para conservarlos del mejor modo posible.',b:'El juez ordenará su destrucción, dejando constancia de sus características.',c:'El juez, oído el Ministerio Fiscal y las partes, resolverá lo que estime conveniente para conservarlos del mejor modo posible.',d:'El juez, tras escuchar al Ministerio Fiscal y al acusado, resolverá lo que estime conveniente, procediendo a su destrucción en el plazo de 15 días.'},correct:'c',why:{c:'El art. 367 ter LECrim establece que cuando los efectos no puedan conservarse, el juez, oído el MF y las partes, resolverá lo que estime conveniente para conservarlos del mejor modo posible.'}}
,{n:114,q:'Según el art. 367 quáter de la LECrim, podrán realizarse los efectos judiciales de lícito comercio, sin esperar al pronunciamiento o firmeza del fallo, siempre que no se trate de piezas de convicción:',o:{a:'Cuando sean perecederos.',b:'Cuando su propietario haga expreso abandono de ellos.',c:'Cuando los gastos de conservación y depósito sean superiores al valor del objeto en sí.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 367 quáter LECrim permite realizar los efectos judiciales sin esperar a la firmeza cuando sean perecederos, cuando el propietario los abandone, o cuando los gastos de conservación superen el valor del objeto.'}}
,{n:115,q:'Según el art. 367 quáter de la LECrim, podrán realizarse los efectos judiciales de lícito comercio, sin esperar a la firmeza del fallo, también:',o:{a:'Cuando su conservación pueda resultar peligrosa para la salud o la seguridad pública.',b:'Cuando se trate de efectos que se deprecien por el transcurso del tiempo.',c:'Cuando debidamente requerido el propietario sobre el destino del efecto judicial, no haga manifestación alguna.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 367 quáter LECrim también permite la realización anticipada cuando la conservación sea peligrosa para la salud, cuando los efectos se deprecien con el tiempo, o cuando el propietario no se manifieste.'}}
,{n:116,q:'Según el art. 367 quinquies de la LECrim, la realización de los efectos judiciales podrá consistir en:',o:{a:'La entrega a entidades sin ánimo de lucro o a las Administraciones públicas.',b:'La realización por medio de entidades privadas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 367 quinquies LECrim establece que la realización de efectos judiciales podrá consistir en la entrega a entidades sin ánimo de lucro o a las Administraciones públicas.'}}
,{n:117,q:'Según el art. 367 quinquies de la LECrim, la realización de los efectos judiciales podrá consistir en:',o:{a:'La realización por medio de persona o entidad especializada.',b:'La subasta pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 367 quinquies LECrim también contempla la realización de efectos judiciales por medio de persona o entidad especializada y mediante subasta pública.'}}
,{n:118,q:'Según el art. 367 quinquies de la LECrim, la realización de los efectos judiciales se llevará a cabo:',o:{a:'Conforme al procedimiento que se determine reglamentariamente.',b:'De conformidad con la legislación civil aplicable.',c:'En los términos que establezca una ley orgánica.',d:'Mediante adjudicación directa.'},correct:'a',why:{a:'El art. 367 quinquies LECrim establece que la realización de efectos judiciales se llevará a cabo conforme al procedimiento que se determine reglamentariamente.'}}
,{n:119,q:'Según el art. 367 quinquies de la LECrim, antes de acordar la realización de efectos judiciales se concederá audiencia:',o:{a:'Al Ministerio Fiscal.',b:'A los interesados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 367 quinquies LECrim establece que antes de acordar la realización de efectos judiciales se concederá audiencia al MF y a los interesados.'}}
,{n:120,q:'Según el artículo 367 sexies de la LECrim, podrá autorizarse la utilización provisional de los bienes o efectos decomisados cautelarmente:',o:{a:'Cuando la utilización de los efectos no permita a la Administración un aprovechamiento de su valor mayor que con la realización anticipada.',b:'Cuando se trate de efectos especialmente idóneos para la prestación de un servicio público.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 367 sexies LECrim permite la utilización provisional de bienes decomisados cuando no sea aprovechable mejor su valor o cuando sean idóneos para un servicio público.'}}
,{n:121,q:'Según el artículo 367 septies de la LECrim, el juez o tribunal podrá encomendar la localización, conservación y la administración de los efectos, bienes, instrumentos y ganancias procedentes de actividades delictivas cometidas en el marco de una organización criminal...',o:{a:'Al Ministerio de Hacienda.',b:'A cualquier administración pública, o entidad privada, en los términos que la ley establezca.',c:'A las Unidades de Policía Judicial especialmente adscritas a juzgados, tribunales o fiscalías.',d:'A la Oficina de Recuperación y Gestión de Activos.'},correct:'d',why:{d:'El art. 367 septies LECrim establece que la localización, conservación y administración de efectos de crimen organizado se encomienda a la Oficina de Recuperación y Gestión de Activos.'}}
,{n:122,q:'Según el artículo 368 de la LECrim, quienes dirijan cargos a determinada persona, con el fin de que no ofrezca duda quién es la persona a que aquellos se refieren, deberán reconocerla judicialmente:',o:{a:'Si el Juez instructor, los acusadores o el mismo inculpado así lo demandan.',b:'Siempre que sean requeridos para ello por la fuerza policial actuante.',c:'Cuando existan dudas razonables de su participación en el delito.',d:'Todas las respuestas anteriores son correctas.'},correct:'a',why:{a:'El art. 368 LECrim establece que deberán reconocerla judicialmente si el Juez instructor, los acusadores o el inculpado así lo demandan.'}}
,{n:123,q:'De acuerdo con el artículo 369 de la LECrim, la diligencia de reconocimiento en rueda se practica poniendo a la vista del que hubiere de verificarlo a la persona que haya de ser reconocida...',o:{a:'Con adopción de las debidas precauciones para evitar que el sometido pueda identificarla.',b:'A quien se hará en unión de otras de circunstancias exteriores semejantes.',c:'Sin permitir a quien realiza la identificación ninguna expresión que pueda alterar el contenido de esta diligencia.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 369 LECrim establece todas estas condiciones para el reconocimiento en rueda: precauciones, acompañamiento de personas semejantes, y prohibición de expresiones que alteren la diligencia.'}}
,{n:124,q:'De acuerdo con el artículo 369 de la LECrim, el que deba verificar la identidad de un sospechoso en la rueda de reconocimiento, en caso afirmativo:',o:{a:'La designará por escrito de manera que no exista lugar a dudas.',b:'La designará clara y determinadamente.',c:'Lo comunicará a su abogado para que éste lo transmita al juez que conozca la causa.',d:'Lo comunicará al Ministerio Fiscal para que lleve a cabo la acusación correspondiente.'},correct:'b',why:{b:'El art. 369 LECrim establece que quien reconozca al sospechoso lo designará clara y determinadamente.'}}
,{n:125,q:'Con respecto a la diligencia de reconocimiento en rueda establecida en la LECrim, indique la afirmación incorrecta:',o:{a:'El que deba verificar el reconocimiento deberá situarse siempre en un punto en el que no pudiere ser visto por las personas a identificar.',b:'Cuando fueren varios los que hubieren de reconocer a una persona, la diligencia deberá practicarse separadamente con cada uno de ellos, sin que puedan comunicarse entre sí.',c:'Cuando fueren varios los que hubieren de ser reconocidos por una misma persona, podrá hacerse el reconocimiento de todos en un mismo acto.',d:'En la diligencia que se extienda han de constar todas las circunstancias del acto, así como los nombres de todos los que hubiesen formado la rueda o grupo.'},correct:'a',why:{a:'El art. 369 LECrim no exige que quien identifica deba situarse en un punto donde no pueda ser visto. Esta afirmación es incorrecta.'}}
,{n:126,q:'El artículo 375 de la LECrim determina que para acreditar la edad del inculpado y comprobar la identidad de su persona:',o:{a:'El Juez instructor traerá al sumario certificación de su inscripción de nacimiento en el Registro Civil, o partida de bautismo, si no estuviese inscrito en ese registro.',b:'El Letrado de la Administración de Justicia traerá al sumario certificación de su inscripción de nacimiento en el Registro Civil.',c:'El Letrado de la Administración de Justicia ordenará a la Policía Judicial traer al sumario la certificación de nacimiento.',d:'El Juez instructor ordenará a la Policía Judicial que traiga al sumario certificación de su inscripción de nacimiento en el Registro Civil, o partida de bautismo, si no estuviese inscrito en ese registro.'},correct:'d',why:{d:'El art. 375 LECrim establece que el Juez instructor ordenará a la Policía Judicial que traiga al sumario la certificación de inscripción de nacimiento del RC o partida de bautismo.'}}
,{n:127,q:'Podrá prescindirse de las certificaciones previstas en el artículo 375 de la LECrim para acreditar la edad del inculpado:',o:{a:'Cuando no ofreciere dudas la identidad del procesado.',b:'Cuando no ofreciere dudas la identidad del procesado y conocidamente tuviese la edad que el Código Penal requiere para la responsabilidad criminal en toda su extensión.',c:'Cuando no ofreciere dudas la identidad del procesado y conocidamente tuviese la edad requerida, si la práctica de estas actuaciones ofreciese alguna dificultad u ocasionase dilaciones extraordinarias.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'c',why:{c:'El art. 375 LECrim permite prescindir de las certificaciones cuando no haya dudas de identidad, tenga la edad penal requerida, y su obtención ofrezca dificultades o dilaciones extraordinarias.'}}
,{n:128,q:'De acuerdo con el artículo 377 de la LECrim, si el Juez instructor lo considerase conveniente, podrá pedir informes sobre el procesado a:',o:{a:'Las Alcaldías del pueblo o pueblos donde hubiese residido.',b:'Los Registros Civiles del pueblo o pueblo donde hubiese residido.',c:'Los puestos de la Guardia Civil del pueblo o pueblos donde hubiese residido.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 377 LECrim establece que el Juez instructor podrá pedir informes sobre el procesado a las Alcaldías, Registros Civiles y puestos de la GC de los lugares donde hubiere residido.'}}
,{n:129,q:'De acuerdo con el artículo 377 de la LECrim, si el Juez instructor lo considerase conveniente, podrá pedir informes sobre el procesado también a:',o:{a:'Las oficinas dependientes de las administraciones públicas de los pueblos o lugares donde hubiese residido.',b:'Los funcionarios de policía del pueblo o pueblos donde hubiese residido.',c:'El Registro Central de Penados y Rebeldes.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 377 LECrim también contempla solicitar informes a las oficinas de administraciones públicas, funcionarios de policía locales y al Registro Central de Penados y Rebeldes.'}}
,{n:130,q:'De acuerdo con el artículo 381 de la LECrim, cuando el juez instructor advirtiere en el procesado indicios de enajenación mental:',o:{a:'Le someterá inmediatamente a la observación de los médicos forenses.',b:'Ordenará el sobreseimiento de la causa penal y la adopción, en su caso, de medidas de aseguramiento sobre el procesado.',c:'Se inhibirá del caso y pondrá al inculpado a disposición de las autoridades sanitarias competentes.',d:'Los tendrá en cuenta al objeto de aplicar las correspondientes atenuantes.'},correct:'a',why:{a:'El art. 381 LECrim establece que cuando el juez observe indicios de enajenación mental en el procesado lo someterá inmediatamente a la observación de los médicos forenses.'}}
,{n:131,q:'Según el artículo 385 de la LECrim, el Juez hará que los procesados presten cuantas declaraciones considere convenientes para la averiguación de los hechos, de oficio o a instancia:',o:{a:'Del Ministerio Fiscal o del querellante particular.',b:'Del acusador privado o del actor civil.',c:'De cualquiera de las partes personadas en el proceso.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 385 LECrim establece que el juez hará que los procesados declaren de oficio o a instancia del MF, querellante, acusador privado, actor civil o cualquier parte personada.'}}
,{n:132,q:'Según el artículo 385 de la LECrim, el Juez hará que los procesados presten cuantas declaraciones considere convenientes para la averiguación de los hechos:',o:{a:'Debiendo estar presentes en el interrogatorio el acusador privado y el actor civil.',b:'Debiendo estar presente en el interrogatorio el acusador privado, pero no el actor civil.',c:'Sin que pueda estar presente en el interrogatorio el acusador privado ni el actor civil.',d:'Sin que pueda estar presente en el interrogatorio el acusador privado, pero sí el actor civil.'},correct:'c',why:{c:'El art. 385 LECrim establece que en el interrogatorio al procesado no pueden estar presentes ni el acusador privado ni el actor civil.'}}
,{n:133,q:'Según el artículo 386 de la LECrim, cuando el procesado estuviere detenido, el juez instructor está obligado a recibirle declaración:',o:{a:'Dentro del término de 48 horas.',b:'Dentro del término de 24 horas.',c:'Dentro del término de 48 horas, pudiendo prorrogarse este plazo por otras 24 horas, si mediare causa grave.',d:'Dentro del término de 24 horas, pudiendo prorrogarse este plazo otras 48 horas, si mediare causa grave.'},correct:'a',why:{a:'El art. 386 LECrim establece que cuando el procesado está detenido, el juez instructor está obligado a recibirle declaración dentro del término de 48 horas.'}}
,{n:134,q:'Según el artículo 389 de la LECrim, durante la declaración de los procesados, las preguntas que les formule el juez instructor:',o:{a:'Serán directas.',b:'No serán capciosas.',c:'No serán sugestivas.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 389 LECrim establece que las preguntas al procesado serán directas, no capciosas y no sugestivas.'}}
,{n:135,q:'En la declaración de los procesados ante el juez instructor:',o:{a:'Las respuestas de éstos serán orales.',b:'El juez les podrá permitir que redacten a su presencia una contestación escrita sobre puntos difíciles de explicar o que consulten apuntes o notas.',c:'No se podrá conminar al procesado con coacción o amenaza alguna.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'En la declaración del procesado las respuestas son orales, el juez puede permitirle redactar contestación escrita para puntos difíciles, y no se puede coaccionarle.'}}
,{n:136,q:'Según el artículo 392 de la LECrim, el juez instructor advertirá al procesado que se continuará la instrucción del proceso, en el caso que...',o:{a:'El procesado rehúse contestar.',b:'El procesado se finja ciego.',c:'El procesado se halle pendiente de examen médico.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 392 LECrim establece que el juez advertirá que se continuará la instrucción si el procesado rehúsa contestar, se finge ciego, o se halla pendiente de examen médico.'}}
,{n:137,q:'Cuando el examen del procesado por el juez instructor se prolongue mucho tiempo o el número de preguntas sea tan considerable que hubiese perdido la serenidad de juicio:',o:{a:'Se suspenderá el examen, concediendo al procesado el tiempo necesario para recuperar la calma.',b:'Se suspenderá el examen, sin que pueda reanudarse antes de transcurridas 12 horas.',c:'Se llevará a cabo un descanso de 30 minutos, continuando seguidamente con el interrogatorio.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'Cuando el examen del procesado se prolongue y éste pierda la serenidad, se suspenderá concediendo el tiempo necesario para recuperar la calma.'}}
,{n:138,q:'Con respecto a la declaración del procesado ante el juez instructor, señale la frase incorrecta:',o:{a:'El procesado podrá declarar cuantas veces quisiere, y el juez le recibirá inmediatamente declaración si tuviese relación con la causa.',b:'En ningún caso podrá hacerse al procesado cargos ni reconvenciones.',c:'Solo se leerá al procesado, si lo pidiere, sus declaraciones anteriores, a no ser que el juez hubiese autorizado la publicidad del sumario.',d:'El procesado no podrá dictar por sí mismo las declaraciones, pero podrá corregir las que dictare el juez instructor.'},correct:'d',why:{d:'La LECrim no prohíbe al procesado dictar sus declaraciones. La opción d es incorrecta ya que el procesado sí puede dictar sus propias declaraciones.'}}
,{n:139,q:'Con respecto a la declaración del procesado ante el juez instructor, indique la respuesta incorrecta:',o:{a:'El procesado podrá dictar por sí mismo las declaraciones.',b:'Si el procesado no dictare por sí mismo las declaraciones, lo hará el juez instructor, procurando consignar las mismas palabras de que aquél se hubiese valido.',c:'El procesado podrá leer su declaración y el juez le enterará de que le asiste este derecho.',d:'El procesado podrá declarar cuantas veces quisiese y el juez le recibirá inmediatamente declaración, si tuviere relación con la causa.'},correct:'c',why:{c:'El art. 393 LECrim no establece expresamente que el procesado tenga derecho a leer su declaración con notificación del juez en esos términos. La opción c es incorrecta.'}}
,{n:140,q:'De acuerdo con el artículo 406 de la LECrim, la confesión del procesado:',o:{a:'Dispensa al juez de instrucción de practicar otras diligencias indagatorias.',b:'No dispensa al juez de instrucción de practicar todas las diligencias necesarias para adquirir conocimiento de la verdad y de la existencia del delito.',c:'Produce la conclusión del sumario, a no ser que existan otras implicaciones cuya responsabilidad no haya quedado suficientemente acreditada.',d:'Tiene naturaleza de prueba preconstituida y entidad suficiente para provocar el cierre de la instrucción.'},correct:'b',why:{b:'El art. 406 LECrim establece que la confesión del procesado no dispensa al juez de instrucción de practicar todas las diligencias necesarias para conocer la verdad.'}}
,{n:141,q:'De acuerdo con el artículo 409 bis de la LECrim, cuando se haya procedido a la imputación de una persona jurídica:',o:{a:'Se tomará declaración al representante designado por ella, asistido de su abogado.',b:'La declaración irá dirigida a la averiguación de los hechos y a la participación en ellos de la entidad imputada.',c:'La incomparecencia del representante determinará que se tenga por celebrado este acto, entendiéndose que se acoge a su derecho a no declarar.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 409 bis LECrim establece: declaración del representante con abogado, objeto de la declaración sobre los hechos, y consecuencias de la incomparecencia.'}}
,{n:142,q:'Según lo establecido en el artículo 410 de la LECrim, tendrán obligación de concurrir al llamamiento judicial para declarar cuanto supieren sobre lo que les fuere preguntado:',o:{a:'Todos los que residan en territorio español, nacionales o extranjeros, que no estén impedidos, si para ello se les cita con las formalidades prescritas en la ley.',b:'Todos los españoles cualquiera que sea el lugar donde se encuentren.',c:'Todos los que residan en territorio español y se hallen en pleno uso de sus derechos civiles y políticos.',d:'Todos los que residan en territorio español y los españoles que residan en el extranjero, si se les cita con las formalidades prescritas en la ley.'},correct:'a',why:{a:'El art. 410 LECrim establece la obligación de declarar a todos los que residan en territorio español, nacionales o extranjeros, que no estén impedidos y sean citados con las formalidades legales.'}}
,{n:143,q:'Según lo establecido en el artículo 411 de la LECrim, están exentos de concurrir al llamamiento judicial y de declarar como testigos:',o:{a:'El Rey, la Reina y sus respectivos consortes.',b:'El Príncipe Heredero.',c:'Los Regentes del Reino.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 411 LECrim establece que están exentos de concurrir y declarar como testigos el Rey, la Reina, sus consortes, el Príncipe Heredero y los Regentes del Reino.'}}
,{n:144,q:'Según lo establecido en el artículo 411 de la LECrim, están exentos de concurrir al llamamiento judicial y de declarar como testigos:',o:{a:'Los agentes Diplomáticos acreditados en España.',b:'El tutor del Rey menor.',c:'El Presidente y demás miembros del Gobierno.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 411 LECrim también exime a los agentes diplomáticos acreditados en España, al tutor del Rey menor y al Presidente y miembros del Gobierno.'}}
,{n:145,q:'Según lo establecido en el artículo 411 de la LECrim, están exentos de concurrir al llamamiento judicial y de declarar como testigos:',o:{a:'El Presidente del Consejo General del Poder Judicial.',b:'El Presidente del Tribunal Constitucional.',c:'El personal administrativo, técnico o de servicio de las misiones diplomáticas, así como sus familiares, si concurren los requisitos exigidos en los Tratados.',d:'Los Fiscales de Sala del Tribunal Supremo.'},correct:'c',why:{c:'El art. 411 LECrim también exime al personal administrativo y técnico de las misiones diplomáticas y sus familiares si concurren los requisitos de los Tratados.'}}
,{n:146,q:'El art.412.2 de la LECrim dispone que está/n exento/s de concurrir al llamamiento del Juez, pero no de declarar, pudiendo informar por escrito sobre los hechos de que tenga/n conocimiento por razón de su cargo:',o:{a:'El Presidente y los demás miembros del Gobierno.',b:'El Presidente del Consejo de Estado.',c:'El Presidente del Tribunal de Cuentas.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 412.2 LECrim establece que el Presidente y miembros del Gobierno, el Presidente del Consejo de Estado y el Presidente del Tribunal de Cuentas pueden informar por escrito sin concurrir al juzgado.'}}
,{n:147,q:'Está/n exento/s de concurrir al llamamiento judicial, pero no de declarar, pudiendo hacerlo por escrito:',o:{a:'El Presidente del Consejo General del Poder Judicial.',b:'Los Secretarios de Estado.',c:'Los Diputados y Senadores.',d:'El Defensor del Pueblo.'},correct:'c',why:{c:'El art. 412 LECrim establece que los Diputados y Senadores están exentos de concurrir al llamamiento judicial pero pueden declarar por escrito.'}}
,{n:148,q:'Está/n exento/s de concurrir al llamamiento judicial, pero no de declarar, pudiendo hacerlo por escrito:',o:{a:'El Fiscal General del Estado.',b:'Los Presidentes de las Comunidades Autónomas.',c:'Los Presidentes del Congreso de los Diputados y del Senado.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 412 LECrim establece que el FGE, los Presidentes de CCAA y los Presidentes del Congreso y Senado están exentos de concurrir pero pueden declarar por escrito.'}}
,{n:149,q:'Está/n exento/s de concurrir al llamamiento judicial, pero no de declarar, pudiendo hacerlo en su Despacho Oficial:',o:{a:'Los Magistrados del Tribunal Constitucional y los vocales del Consejo General del Poder Judicial.',b:'El Letrado Mayor de las Cortes Generales.',c:'El Príncipe Heredero.',d:'Los agentes diplomáticos acreditados en España.'},correct:'a',why:{a:'El art. 412 LECrim establece que los Magistrados del TC y los vocales del CGPJ pueden declarar en su Despacho Oficial sin concurrir al llamamiento judicial.'}}
,{n:150,q:'Está/n exento/s de concurrir al llamamiento judicial, pero no de declarar, pudiendo hacerlo en su Despacho Oficial:',o:{a:'Los Fiscales de Sala del Tribunal Supremo.',b:'El Defensor del Pueblo.',c:'Los Diputados y Senadores.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 412 LECrim establece que los Fiscales de Sala del TS, el Defensor del Pueblo y los Diputados y Senadores pueden declarar en su Despacho Oficial.'}}
,{n:151,q:'Está/n exento/s de concurrir al llamamiento judicial, pero no de declarar, pudiendo hacerlo en su Despacho Oficial:',o:{a:'Los Regentes del Reino.',b:'Las autoridades judiciales de cualquier orden jurisdiccional, de categoría superior a la del que recibiere la declaración.',c:'El tutor o tutores del Rey menor.',d:'El Jefe de la Casa Real.'},correct:'b',why:{b:'El art. 412 LECrim establece que las autoridades judiciales de categoría superior al que recibe la declaración pueden declarar en su Despacho Oficial.'}}
,{n:152,q:'Están exentos de concurrir al llamamiento judicial, pero no de declarar, pudiendo hacerlo en su Despacho Oficial:',o:{a:'Los Presidentes de las Asambleas Legislativas de las Comunidades Autónomas.',b:'Los Alcaldes de Madrid y Barcelona.',c:'Los miembros de las Oficinas Consulares.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 412 LECrim contempla que los Presidentes de Asambleas Legislativas autonómicas, los Alcaldes de Madrid y Barcelona, y los miembros de las Oficinas Consulares pueden declarar en su Despacho.'}}
,{n:153,q:'Están exentos de concurrir al llamamiento judicial, pero no de declarar, pudiendo hacerlo en su Despacho Oficial:',o:{a:'El Presidente y los Consejeros Permanentes del Consejo de Estado.',b:'El Presidente y los Consejeros del Tribunal de Cuentas.',c:'Los miembros del Consejo de Gobierno de las Comunidades Autónomas.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 412 LECrim también incluye al Presidente y Consejeros del Consejo de Estado, del Tribunal de Cuentas y a los miembros de los Consejos de Gobierno autonómicos.'}}
,{n:154,q:'Están exentos de concurrir al llamamiento judicial, pero no de declarar, pudiendo hacerlo en su Despacho Oficial:',o:{a:'Los Secretarios y Subsecretarios de Estado.',b:'Los Delegados del Gobierno en las Comunidades Autónomas y los Subdelegados del Gobierno en la Provincia.',c:'Los Delegados de Hacienda.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 412 LECrim incluye entre quienes pueden declarar en su Despacho a los Secretarios y Subsecretarios de Estado, Delegados y Subdelegados del Gobierno, y Delegados de Hacienda.'}}
,{n:155,q:'De acuerdo con el artículo 416.1 de la LECrim están dispensados de la obligación de declarar:',o:{a:'Los parientes del procesado en línea directa ascendente y descendente.',b:'Colaterales consanguíneos hasta cuarto grado civil.',c:'Afines de hasta segundo grado, si viviesen juntos.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 416.1 LECrim dispensa de la obligación de declarar a los parientes directos, colaterales consanguíneos hasta 4º grado y afines hasta 2º grado si viven juntos.'}}
,{n:156,q:'De acuerdo con el artículo 416.1 de la LECrim están dispensados de la obligación de declarar:',o:{a:'Los funcionarios de la Policía Judicial por los hechos e informaciones que conocieren en el ejercicio de sus cargos.',b:'Los funcionarios de categoría superior al encausado, que no pudieren hacerlo sin violar su juramento o promesa de guardar secreto.',c:'Los hermanos consanguíneos o uterinos del procesado y los colaterales consanguíneos hasta segundo grado civil.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 416.1 LECrim también dispensa a los funcionarios de PJ por hechos conocidos en su cargo, funcionarios con secreto profesional, y hermanos y colaterales hasta 2º grado.'}}
,{n:157,q:'Las dispensas a la obligación de declarar como testigo, que contiene el artículo 416.1 de la LECrim, no son de aplicación...',o:{a:'Cuando el testigo haya aceptado declarar durante el procedimiento, después de haber sido advertido de que todo lo que diga puede ser utilizado en su contra.',b:'Cuando por razón de edad o ignorancia el testigo no pueda comprender el sentido de la dispensa.',c:'Cuando el testigo esté o haya estado personado en el procedimiento como acusación particular.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 416.1 LECrim establece que la dispensa no se aplica cuando el testigo aceptó declarar, cuando no pueda comprender la dispensa por edad o ignorancia, o cuando esté personado como acusación particular.'}}
,{n:158,q:'Las dispensas a la obligación de declarar como testigo que contiene el artículo 416.1 de la LECrim, no son de aplicación...',o:{a:'Cuando se trate de un delito grave o menos grave, el testigo sea mayor de edad y la víctima sea persona menor de edad o con discapacidad necesitada de especial protección.',b:'Cuando el testigo tenga atribuida la representación legal, tutela, curatela, guarda o acogimiento de la víctima menor de edad o con discapacidad.',c:'Cuando el testigo haya aceptado declarar durante el procedimiento, después de haber sido informado de su derecho a no hacerlo.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'Las dispensas del art. 416.1 LECrim tampoco se aplican cuando la víctima sea menor o discapacitada representada por el testigo, ni cuando el testigo haya renunciado voluntariamente a la dispensa.'}}
,{n:159,q:'De acuerdo con el artículo 416.2 de la LECrim están dispensados de la obligación de declarar:',o:{a:'Los abogados de los procesados con respecto a los hechos que estos les hubieren confiado en su calidad de defensor.',b:'Los traductores e intérpretes de las conversaciones y comunicaciones entre el imputado, procesado o acusado y su abogado, con relación a los hechos a que estuviera referida su traducción o interpretación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 416.2 LECrim dispensa a los abogados defensores de los procesados y a los traductores e intérpretes de sus conversaciones con el abogado.'}}
,{n:160,q:'De acuerdo con el artículo 417 de la LECrim, no podrán ser obligados a declarar como testigos:',o:{a:'Los Fiscales de Sala del Tribunal Supremo.',b:'Los eclesiásticos y ministros de cultos disidentes, sobre los hechos que les fueren revelados en el ejercicio de las funciones de su Ministerio.',c:'El Defensor del Pueblo.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 417 LECrim establece que no pueden ser obligados a declarar los Fiscales de Sala del TS, los eclesiásticos sobre hechos revelados en su ministerio, y el Defensor del Pueblo.'}}
,{n:161,q:'De acuerdo con el artículo 417 de la LECrim, no podrán ser obligados a declarar como testigos:',o:{a:'Los funcionarios públicos, de cualquier clase, cuando no pudieren declarar sin violar el secreto que por razón de sus cargos estuviesen obligados a guardar.',b:'Los incapacitados, física o moralmente.',c:'Los eclesiásticos y ministros de cultos disidentes, sobre los hechos que les fueren revelados en el ejercicio de las funciones de su Ministerio.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 417 LECrim también incluye entre quienes no pueden ser obligados a declarar a los funcionarios con secreto de cargo, los incapacitados físicos o morales, y los eclesiásticos sobre confesiones.'}}
,{n:162,q:'De acuerdo con el artículo 417 de la LECrim, no podrán ser obligados a declarar como testigos:',o:{a:'Los funcionarios públicos que procediendo en virtud de obediencia debida, no fueren autorizados por su superior jerárquico para prestar la declaración que se les pide.',b:'Las autoridades judiciales de cualquier orden jurisdiccional, de categoría superior a la de aquel que recibiere la declaración.',c:'Los funcionarios de la Policía Judicial que no sean debidamente autorizados por sus superiores jerárquicos, en asuntos que conozcan por razón de sus cargos.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 417 LECrim también contempla que no pueden ser obligados a declarar los funcionarios con obediencia debida no autorizados, las autoridades judiciales superiores, y los funcionarios de PJ no autorizados.'}}
,{n:163,q:'De conformidad con lo establecido en el artículo 418 de la LECrim....',o:{a:'Ningún testigo podrá ser obligado a declarar acerca de una pregunta cuya contestación pueda perjudicarle materialmente y de manera directa a cualquier persona ligada por análoga relación de afectividad a la del matrimonio.',b:'Ningún testigo podrá ser obligado a declarar acerca de una pregunta cuya contestación pueda perjudicarle moralmente, a uno de sus ascendientes.',c:'Ningún testigo podrá ser obligado a declarar acerca de una pregunta cuya contestación pueda perjudicarle material o moralmente, y de manera directa o indirecta, a alguno de sus colaterales consanguíneos de hasta tercer grado civil.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'d',why:{d:'El art. 418 LECrim establece la protección contra preguntas que perjudiquen al testigo, pero en términos diferentes a los descritos en las opciones a, b y c. Ninguna reproduce fielmente el artículo.'}}
,{n:164,q:'De conformidad con lo dispuesto en el artículo 419 de la LECrim, si el testigo estuviere físicamente impedido de acudir al llamamiento judicial, el Juez instructor se constituirá en su domicilio, siempre y cuando....',o:{a:'La causa investigada sea por delito grave.',b:'No hubiere otra forma más adecuada de recibirle declaración.',c:'Así lo pidiere alguna de las partes personadas en el proceso.',d:'No se ponga en peligro la vida del enfermo.'},correct:'d',why:{d:'El art. 419 LECrim establece que el Juez se constituirá en el domicilio del testigo impedido siempre y cuando no se ponga en peligro la vida del enfermo.'}}
,{n:165,q:'El que sin estar impedido no concurriere al primer llamamiento judicial o se resistiere a declarar lo que supiese acerca de los hechos sobre los que fuere preguntado:',o:{a:'Incurrirá en un delito de desobediencia.',b:'Incurrirá en un delito de denegación de auxilio a la justicia.',c:'Incurrirá en multa de 200 a 5000 euros.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'c',why:{c:'El art. 420 LECrim establece que quien sin estar impedido no concurra al primer llamamiento o se resista a declarar incurrirá en multa de 200 a 5.000 euros.'}}
,{n:166,q:'Según lo establecido en la LECrim y con respecto a la declaración de testigos, indique la afirmación incorrecta:',o:{a:'Si el testigo estuviere físicamente impedido de acudir al llamamiento judicial, el Juez instructor que hubiere de recibirle la declaración se constituirá en su domicilio, siempre que el interrogatorio no haya de poner en peligro la vida del enfermo.',b:'Los testigos declararán conjunta o separadamente, a presencia del Juez instructor, de la policía judicial y del Letrado de la Administración de Justicia.',c:'Los testigos mayores de edad prestarán juramento o promesa de decir todo lo que supieren respecto a lo que les fuere preguntado, el juez obligado a informarles de la posibilidad de incurrir en un delito de falso testimonio en causa criminal.',d:'Los testigos que tengan la condición de víctima del delito podrán hacerse acompañar por su representante legal y por una persona de su elección durante la práctica de estas diligencias.'},correct:'b',why:{b:'Los testigos no declaran en presencia de la policía judicial. Declaran ante el Juez instructor y el LAJ. La presencia de la policía no está prevista en esa fase.'}}
,{n:167,q:'Respecto a la declaración de testigos, la LECrim establece que:',o:{a:'Los testigos declararán separada y secretamente a presencia del Juez instructor y del Letrado de la Administración de Justicia.',b:'Si el testigo fuese sordo se nombrará un intérprete de lengua de signos adecuado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'La LECrim establece que los testigos declaran separada y secretamente ante el Juez y el LAJ, y que si el testigo fuere sordo se nombrará un intérprete de lengua de signos.'}}
,{n:168,q:'El que sin estar impedido no concurriere al primer llamamiento judicial incurrirá en multa de 200 a 5.000 euros y si persistiere en su resistencia:',o:{a:'Será conducido a presencia del Juez instructor por los agentes de la autoridad.',b:'Será perseguido por un delito de obstrucción a la Justicia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'a',why:{a:'El art. 420 LECrim establece que si el testigo persiste en su resistencia será conducido a presencia del Juez instructor por los agentes de la autoridad.'}}
,{n:169,q:'El que se resistiere a declarar lo que supiese acerca de los hechos sobre los que fuere preguntado en llamamiento judicial, incurrirá en multa de 200 a 5.000 euros y si persistiere en su resistencia:',o:{a:'Será perseguido por delito de desobediencia grave.',b:'Será perseguido por un delito de obstrucción a la Justicia y también por un delito de desobediencia grave.',c:'Será perseguido por un delito de denegación de auxilio a la justicia.',d:'Será perseguido por un delito de obstrucción a la Justicia.'},correct:'c',why:{c:'El art. 420 LECrim establece que si persiste en no declarar será perseguido por un delito de denegación de auxilio a la justicia.'}}
,{n:170,q:'Cuando se haya de tomar declaración a testigos menores de edad o personas con capacidad judicialmente modificada, el juez podrá:',o:{a:'Acordar que se les tome la declaración mediante la intervención de expertos y con intervención del Ministerio Fiscal.',b:'Excluir o limitar la presencia de las partes en el lugar de la exploración de la víctima, ordenando la grabación de la declaración por medios audiovisuales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 433 LECrim establece que para testigos menores o con capacidad modificada, el juez puede acordar la intervención de expertos con el MF y excluir a las partes ordenando grabación audiovisual.'}}
,{n:171,q:'Cuando un testigo residiere fuera del partido judicial del juez que instruye el sumario, el juez instructor:',o:{a:'Mandará que comparezca ante él inmediatamente.',b:'Le concederá un plazo de 5 días para que comparezca a su presencia.',c:'Se abstendrá de mandarle comparecer a su presencia, constituyendo una comisión judicial que se desplazará al domicilio del testigo.',d:'Se abstendrá de mandarle comparecer a su presencia, a no ser que lo considere absolutamente necesario para la comprobación del delito o para el reconocimiento de la persona del delincuente, en cuyo caso lo ordenará mediante auto motivado.'},correct:'d',why:{d:'El art. 421 LECrim establece que si el testigo reside fuera del partido judicial, el juez se abstendrá de hacerle comparecer salvo que sea absolutamente necesario, y lo ordenará mediante auto motivado.'}}
,{n:172,q:'Con respecto a la citación de testigos durante la instrucción del procedimiento penal, señale la respuesta incorrecta:',o:{a:'Los testigos podrán ser citados personalmente donde fueren habidos, cuando proceda.',b:'Si el testigo estuviere ausente del territorio español, se prescindirá de su testimonio y no se le citará.',c:'Cuando sea urgente el examen de un testigo, se le podrá citar verbalmente para que comparezca en el acto, haciendo constar el motivo de la urgencia.',d:'El juez instructor podrá constituirse en el domicilio de un testigo o en el lugar en que se encuentre para recibirle declaración.'},correct:'b',why:{b:'La LECrim no establece que se prescinda del testimonio si el testigo está en el extranjero. Se puede recurrir a la cooperación judicial internacional. La opción b es incorrecta.'}}
,{n:173,q:'Con respecto a la declaración de testigos ante el juez instructor, indique la respuesta incorrecta:',o:{a:'Los testigos declararán de viva voz, sin que les esté permitido leer declaración ni respuesta alguna que lleven escrita.',b:'Los testigos, durante su declaración, no podrán consultar apunte o memoria alguna, aunque ésta contenga datos difíciles de recordar.',c:'El testigo podrá dictar las contestaciones por sí mismo.',d:'Al testigo no se le harán preguntas capciosas ni sugestivas.'},correct:'b',why:{b:'El art. 436 LECrim permite a los testigos consultar apuntes o memoria cuando contengan datos difíciles de recordar. La opción b que dice que no pueden consultar ningún apunte es incorrecta.'}}
,{n:174,q:'Con respecto a la declaración de testigos ante el juez instructor, indique la respuesta incorrecta:',o:{a:'Aquellos testigos que tengan la condición de víctimas del delito podrán hacerse acompañar por su representante legal.',b:'El Juez instructor puede habilitar a los agentes de policía para practicar las diligencias de citación verbal o escrita si lo considera conveniente.',c:'Aquellos testigos que tengan la condición de víctimas del delito podrán hacerse acompañar por una persona de su elección, salvo que el Juez de instrucción resuelva motivadamente lo contrario.',d:'Los testigos serán formados en la forma establecida en el Título V del Libro Primero de la Ley de Enjuiciamiento Criminal.'},correct:'b',why:{b:'El Juez instructor no puede habilitar a agentes de policía para practicar citaciones de testigos. Esto es competencia del órgano judicial. La opción b es incorrecta.'}}
,{n:175,q:'De conformidad con el artículo 449 bis de la LECrim, cuando la autoridad judicial acuerde la práctica de la declaración del testigo como prueba preconstituida...',o:{a:'Se garantizará el principio de publicidad.',b:'Se garantizará el principio de transparencia.',c:'Se garantizará el principio de contradicción.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 449 bis LECrim establece que cuando se acuerde la declaración como prueba preconstituida se garantizarán los principios de publicidad, transparencia y contradicción.'}}
,{n:176,q:'De conformidad con el artículo 449 bis de la LECrim, cuando la autoridad judicial acuerde la práctica de la declaración del testigo como prueba preconstituida...',o:{a:'La no comparecencia de la persona investigada debidamente citada no impedirá la práctica de la prueba, pero su defensa letrada deberá estar presente en todo caso.',b:'La autoridad judicial asegurará la documentación de la declaración en un soporte apto para la grabación del sonido y de la imagen.',c:'Se acompañará acta sucinta autorizada por el Letrado de la Administración de Justicia que contendrá todas las firmas de las personas intervinientes.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 449 bis LECrim establece todas estas garantías: defensa presente aunque no comparezca el investigado, documentación audiovisual, y acta del LAJ con todas las firmas.'}}
,{n:177,q:'De conformidad con el artículo 449 bis de la LECrim, cuando la autoridad judicial acuerde la práctica de la declaración del testigo como prueba preconstituida y no comparezca el defensor de la persona investigada...',o:{a:'El acto se sustanciará con el abogado de oficio expresamente designado al efecto, en todo caso.',b:'El acto se sustanciará con el abogado de oficio expresamente designado al efecto, siempre que concurran razones de urgencia.',c:'El acto se sustanciará con el abogado de oficio expresamente designado al efecto, si ninguna de las partes realizare objeción en contra.',d:'El acto se sustanciará con el abogado de oficio expresamente designado al efecto, siempre y cuando no sea recusado por ninguna de las partes.'},correct:'a',why:{a:'El art. 449 bis LECrim establece que si no comparece el defensor, el acto se sustanciará con el abogado de oficio expresamente designado al efecto, en todo caso.'}}
,{n:178,q:'De conformidad con el artículo 449 bis de la LECrim, la valoración de la prueba preconstituida se llevará a cabo conforme a lo dispuesto en...',o:{a:'El artículo 770.2 de la Ley de Enjuiciamiento Criminal.',b:'El artículo 740.2 de la Ley de Enjuiciamiento Criminal.',c:'El artículo 730.2 de la Ley de Enjuiciamiento Criminal.',d:'El artículo 772.2 de la Ley de Enjuiciamiento Criminal.'},correct:'c',why:{c:'El art. 449 bis LECrim establece que la valoración de la prueba preconstituida se llevará a cabo conforme a lo dispuesto en el art. 730.2 LECrim.'}}
,{n:179,q:'De conformidad con el artículo 449 ter de la LECrim, la autoridad judicial acordará, en todo caso, practicar como prueba preconstituida la audiencia de un menor de 14 años que deba intervenir como testigo, siempre y cuando el procedimiento tenga por objeto la instrucción de un delito ...',o:{a:'Contra el patrimonio.',b:'Contra las relaciones familiares.',c:'Contra el honor.',d:'Contra el mercado y los consumidores.'},correct:'a',why:{a:'El art. 449 ter LECrim establece la obligación de practicar prueba preconstituida cuando el menor de 14 años deba testificar en delitos contra el patrimonio, entre otros.'}}
,{n:180,q:'De conformidad con el artículo 449 ter de la LECrim, la autoridad judicial acordará, en todo caso, practicar como prueba preconstituida la audiencia de un menor de 14 años que deba intervenir como testigo, siempre y cuando el procedimiento tenga por objeto la instrucción de un delito ...',o:{a:'Contra la libertad e indemnidad sexuales.',b:'Contra la salud pública.',c:'Contra la administración pública.',d:'Contra la omisión de perseguir delitos.'},correct:'a',why:{a:'El art. 449 ter LECrim obliga a practicar prueba preconstituida especialmente cuando el menor deba testificar en delitos contra la libertad e indemnidad sexuales.'}}
,{n:181,q:'De conformidad con el artículo 449 ter de la LECrim, la autoridad judicial acordará, en todo caso, practicar como prueba preconstituida la audiencia de un menor de 14 años que deba intervenir como testigo, cuando el delito sea...',o:{a:'Contra la administración de justicia.',b:'Contra la administración de justicia de la Corte Penal Internacional.',c:'Contra la trata de seres humanos.',d:'Contra la Corona.'},correct:'c',why:{c:'El art. 449 ter LECrim también obliga a la prueba preconstituida cuando el menor testifique en delitos de trata de seres humanos.'}}
,{n:182,q:'De conformidad con el artículo 449 ter de la LECrim, la autoridad judicial acordará, en todo caso, practicar como prueba preconstituida la audiencia de un menor de 14 años que deba intervenir como testigo, cuando el delito sea...',o:{a:'Lesiones.',b:'Homicidio.',c:'Contra la integridad moral.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 449 ter LECrim establece la obligación de prueba preconstituida también en delitos de lesiones, homicidio y contra la integridad moral.'}}
,{n:183,q:'De conformidad con el artículo 449 ter de la LECrim, la autoridad judicial acordará, en todo caso, practicar como prueba preconstituida la audiencia de un menor de 14 años que deba intervenir como testigo, cuando el delito sea...',o:{a:'Contra el ejercicio de derechos fundamentales y libertades públicas.',b:'Contra el orden público.',c:'Contra la paz e independencia del Estado.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 449 ter LECrim también incluye los delitos contra derechos fundamentales, el orden público y la paz e independencia del Estado como supuestos de prueba preconstituida obligatoria.'}}
,{n:184,q:'En la LECrim, el careo de los testigos y procesados comprende los artículos...',o:{a:'450 a 456.',b:'451 a 455.',c:'451 a 455.',d:'451 a 456.'},correct:'b',why:{b:'El careo de testigos y procesados en la LECrim comprende los artículos 451 a 455.'}}
,{n:185,q:'Según la LECrim y en lo que se refiere a la diligencia de careo, indique la respuesta incorrecta...',o:{a:'Esta diligencia se puede llevar a cabo con testigos o con procesados, o con estos entre sí.',b:'Como regla general, esta diligencia solo puede celebrarse con un máximo de tres personas a la vez.',c:'El careo se verifica ante el Juez.',d:'El Letrado de la Administración de Justicia leerá a los procesados o testigos entre quienes tenga lugar el acto, las declaraciones que hubieren prestado.'},correct:'b',why:{b:'La LECrim no establece un máximo de tres personas para el careo. Esta limitación no existe en la ley. La opción b es incorrecta.'}}
,{n:186,q:'Según la LECrim y en lo que se refiere a la diligencia de careo, indique la respuesta incorrecta...',o:{a:'Esta diligencia no tendrá lugar, como regla general, más que entre dos personas a la vez.',b:'Como regla general, esta diligencia solo puede celebrarse con un máximo de tres personas a la vez.',c:'El careo se verifica ante el Juez.',d:'El Letrado de la Administración de Justicia leerá a los procesados o testigos entre quienes tenga lugar el acto, las declaraciones que hubieren prestado.'},correct:'b',why:{b:'El art. 455 LECrim establece que el careo tiene lugar, como regla general, entre dos personas a la vez, no un máximo de tres. La opción b es incorrecta.'}}
,{n:187,q:'De acuerdo con el artículo 453 de la LECrim, de las preguntas, contestaciones y actitudes de los comparecientes en el acto de un careo, dará fe:',o:{a:'El Letrado de la Administración de Justicia.',b:'El funcionario de la Policía Judicial encargado de la diligencia.',c:'El Juez Instructor.',d:'El Ministerio Fiscal.'},correct:'a',why:{a:'El art. 453 LECrim establece que de las preguntas, contestaciones y actitudes en el careo dará fe el Letrado de la Administración de Justicia.'}}
,{n:188,q:'De acuerdo con el artículo 455 de la LECrim, no se practicarán careos sino cuando fuere conocido otro modo de comprobar:',o:{a:'La existencia del delito.',b:'La culpabilidad de alguno de los procesados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 455 LECrim establece que no se practicarán careos sino cuando no fuere conocido otro modo de comprobar la existencia del delito o la culpabilidad de los procesados.'}}
,{n:189,q:'De acuerdo con el artículo 455 de la LECrim el careo con testigos que sean menores de edad:',o:{a:'Está total y absolutamente prohibido.',b:'Está permitido si media autorización de los padres o tutores de los menores careados.',c:'Solo está permitido si lo autoriza el juez de menores o el funcionario del Ministerio Fiscal encargado de la causa.',d:'Solo está permitido cuando el juez lo considere imprescindible y no lesivo para los intereses de dichos testigos, previo informe pericial.'},correct:'d',why:{d:'El art. 455 LECrim establece que el careo con testigos menores solo está permitido cuando el juez lo considere imprescindible y no lesivo para sus intereses, previo informe pericial.'}}
,{n:190,q:'Según lo establecido en la LECrim con respecto al careo, señale la respuesta incorrecta:',o:{a:'El juez podrá celebrarlo cuando los testigos o los procesados entre sí o aquéllos con éstos, discordaren acerca de algún hecho o circunstancia que interese al sumario.',b:'Debe estar presente en el mismo el funcionario de la policía judicial que practicó la detención o detenciones, y los abogados defensores de los careados.',c:'Se verificará ante el juez, leyendo el Secretario a los procesados o testigos entre quienes tenga lugar el acto, las declaraciones que hubieren prestado.',d:'Esta diligencia no tendrá lugar, como regla general, más que entre dos personas a la vez y el juez no permitirá que los careados se insulten o amenacen.'},correct:'b',why:{b:'El art. 451 LECrim no exige la presencia del funcionario de policía que practicó la detención en el careo. Esta es una afirmación incorrecta.'}}
,{n:191,q:'De acuerdo con el artículo 456 de la LECrim, el Juez acordará el informe pericial cuando, para conocer o apreciar algún hecho o circunstancia importante en el sumario, fuesen necesarios o convenientes:',o:{a:'Conocimientos científicos o artísticos.',b:'Conocimientos especializados en psicología y criminología.',c:'Conocimientos que no posea sobre cualquier circunstancia personal o social.',d:'Conocimientos especializados sobre materias que no sea objeto de una carrera jurídica.'},correct:'a',why:{a:'El art. 456 LECrim establece que el informe pericial procede cuando sean necesarios o convenientes conocimientos científicos o artísticos.'}}
,{n:192,q:'De conformidad con el artículo 457 de la LECrim:',o:{a:'Los peritos pueden ser o no titulares.',b:'Son peritos titulares los que tienen título oficial de una ciencia o arte cuyo ejercicio esté reglamentado por la Administración.',c:'Son peritos no titulares los que, careciendo de título oficial, tienen, sin embargo, conocimientos o práctica especial en alguna ciencia o arte.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 457 LECrim establece todas estas categorías: peritos titulares con título oficial reglamentado, y peritos no titulares con conocimientos especiales sin título oficial.'}}
,{n:193,q:'De acuerdo con el artículo 457 de la LECrim, los peritos no titulares:',o:{a:'No tienen título oficial.',b:'No pueden prestar informes periciales.',c:'Deben haber obtenido una habilitación del Ministerio de Justicia.',d:'Todas las respuestas anteriores son incorrectas.'},correct:'d',why:{d:'Las opciones a, b y c son incorrectas. Los peritos no titulares sí pueden prestar informes periciales sin habilitación del Ministerio de Justicia, aunque carezcan de título oficial.'}}
,{n:194,q:'De acuerdo con lo dispuesto en la LECrim, en lo que respecta a la prueba pericial, se dispone que todo reconocimiento se llevará a cabo...',o:{a:'Por un perito, bajo la dirección del Letrado de la Administración de Justicia, que dará fe de lo acontecido.',b:'Por dos peritos, bajo la dirección del Letrado de la Administración de Justicia, que dará fe de lo acontecido.',c:'Como regla general por dos peritos, aunque uno de ellos podrá ser suplido por el Letrado de la Administración de Justicia.',d:'Por dos peritos, salvo que no hubiese más de uno en el lugar y no fuere posible esperar la llegada de otro sin graves inconvenientes para el sumario.'},correct:'d',why:{d:'El art. 459 LECrim establece que el reconocimiento pericial se llevará a cabo por dos peritos, salvo que no hubiere más de uno en el lugar y no fuera posible esperar la llegada de otro.'}}
,{n:195,q:'De acuerdo con la LECrim, con respecto a los peritos, indique la afirmación incorrecta:',o:{a:'El Juez se valdrá de peritos titulares con preferencia sobre los que no tuviesen título.',b:'Podrán prestar informe pericial acerca del delito, cualquiera que sea la persona ofendida, los que según el art. 416 de la LECrim no están obligados a declarar como testigos.',c:'Nadie puede negarse a acudir al llamamiento del Juez para desempeñar un servicio pericial, si no estuviere legítimamente impedido.',d:'Los que presten informe como peritos en virtud de orden judicial tendrán derecho a reclamar los honorarios e indemnizaciones que sean justos.'},correct:'b',why:{b:'La dispensa de declarar del art. 416 LECrim no se extiende automáticamente a la pericial. Los peritos mencionados en el art. 416 sí pueden ser obligados a peritar. La opción b es incorrecta.'}}
,{n:196,q:'De acuerdo con la LECrim, con respecto a los peritos, indique la respuesta correcta:',o:{a:'Nadie puede negarse a acudir al llamamiento del Juez para desempeñar un servicio pericial, si no estuviere legítimamente impedido.',b:'El perito que sin alegar excusa fundada deje de acudir al llamamiento del Juez o se negare a prestar el informe incurrirá en las responsabilidades señaladas para los testigos en el artículo 420 de esta Ley.',c:'No pueden prestar informe pericial acerca del delito, cualquiera que sea la persona ofendida, los que según el artículo 416 de esta ley no estén obligados a declarar como testigos.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'Las opciones a, b y c son todas correctas conforme a la regulación pericial de la LECrim.'}}
,{n:197,q:'De acuerdo con el artículo 466 de la LECrim, hecho el nombramiento de peritos, el Letrado de la Administración de Justicia lo notificará inmediatamente a...',o:{a:'El actor particular, si lo hubiere.',b:'Al representante del procesado, si lo tuviere.',c:'Al Ministerio Fiscal.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 466 LECrim establece que el LAJ notificará el nombramiento de peritos al actor particular si lo hubiere, al representante del procesado si lo tuviere, y al Ministerio Fiscal.'}}
,{n:198,q:'El atestado es el documento donde se contienen y extienden todas las diligencias realizadas por la Policía Judicial para:',o:{a:'La investigación de un hecho aparentemente delictivo.',b:'El descubrimiento de los delincuentes y el aseguramiento del cuerpo del delito.',c:'La adopción de medidas provisionales y cautelares, en su caso.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El atestado es el documento donde la PJ recoge todas las diligencias para la investigación del hecho, el descubrimiento de delincuentes, y la adopción de medidas cautelares.'}}
,{n:199,q:'De acuerdo con el artículo 292 de la LECrim y con respecto al atestado, indique la afirmación incorrecta:',o:{a:'Antes de su entrega a la autoridad judicial, el Letrado de la Administración de Justicia lo examina y lo diligencia.',b:'Lo extienden los funcionarios de la Policía Judicial.',c:'Puede extenderse en papel sellado o en papel común.',d:'Debe contener las declaraciones e informes recibidos.'},correct:'a',why:{a:'El art. 292 LECrim no establece que el LAJ examine y diligencie el atestado antes de su entrega a la autoridad judicial. Esta afirmación es incorrecta.'}}
,{n:200,q:'De acuerdo con la LECrim y con respecto al atestado, indique la afirmación incorrecta:',o:{a:'Debe ser firmado por el que lo haya extendido y si usare sello lo estampará con su rúbrica en todas las hojas.',b:'Deben firmarlo los peritos y testigos que hubiesen intervenido en las diligencias, y si no lo hicieren podrán ser recusados por las partes.',c:'Puede sustituirse por una relación verbal circunstanciada que reducirá a escrito de un modo fehaciente el funcionario del MF, el Juez de Instrucción o el municipal a quien deba presentarse el atestado.',d:'Debe acompañarse de un informe dando cuenta de las detenciones anteriores y de la existencia de requisitorias para su llamamiento y busca.'},correct:'b',why:{b:'El art. 293 LECrim no establece que los testigos y peritos deban firmar el atestado so pena de recusación. Esta afirmación es incorrecta.'}}
,{n:201,q:'Según el artículo 292 de la LECrim, la Policía Judicial remitirá con el atestado:',o:{a:'Copia de las fichas policiales de los detenidos, cuando las hubiere.',b:'Un informe de conducta de los responsables del delito, cuando sean conocidos.',c:'Un informe dando cuenta de las detenciones anteriores de los responsables y de la existencia de requisitorias para su llamamiento y búsqueda, cuando así conste en sus bases de datos.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 292 LECrim establece que junto al atestado se remitirán las fichas policiales, el informe de conducta y el informe de detenciones anteriores y requisitorias.'}}
,{n:202,q:'De acuerdo con el artículo 293 de la LECrim:',o:{a:'El atestado será firmado por el que lo haya extendido y, si usare sello, lo estampará con su rúbrica en todas sus hojas.',b:'Serán invitadas a firmar en la parte a ellos referentes, las personas presentes que hubieren intervenido en las diligencias que se relacionan en un atestado, haciendo constar la razón si no lo hicieren.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 293 LECrim establece que el atestado será firmado por quien lo extendió estampando su rúbrica, y que se invitará a firmar a las personas que hubieren intervenido en las diligencias.'}}
,{n:203,q:'De acuerdo con la LECrim y con respecto al atestado, indique la afirmación correcta:',o:{a:'En ningún caso los funcionarios de la Policía Judicial podrán dejar transcurrir más de 24 horas sin dar conocimiento a la autoridad judicial o Ministerio Fiscal de las diligencias practicadas, salvo en los supuestos de fuerza mayor.',b:'En el atestado se consignarán todas las circunstancias, tanto las que sean adversas como las favorables al presunto reo.',c:'En el atestado se relatará el hecho expresando con la mayor claridad posible los extremos denunciados y observados, omitiéndose, en lo posible, las impresiones y apreciaciones subjetivas o irrelevantes.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'Todas las afirmaciones son correctas: el plazo de 24h salvo fuerza mayor, la consignación de circunstancias adversas y favorables, y la claridad y objetividad en la relación de hechos.'}}
,{n:204,q:'Sujeto del atestado es:',o:{a:'El Instructor, o persona que lo redacta y que normalmente será un funcionario de Policía.',b:'El denunciante, o persona que pone en conocimiento de la autoridad unos hechos presuntamente delictivos y que puede ser, o no, ofendido o víctima.',c:'El/los testigo/s, que como mínimo serán identificados con su filiación completa, con el fin de que la autoridad judicial pueda citarlos e interrogarlos.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El atestado tiene como sujetos al instructor que lo redacta, al denunciante que pone en conocimiento los hechos, y a los testigos identificados con su filiación completa.'}}
,{n:205,q:'Según el art.772.2 de la LECrim, la Policía extenderá el atestado y lo entregará al Juzgado competente, pondrá a su disposición a los detenidos, si los hubiere, y remitirá copia:',o:{a:'Al abogado del detenido, si lo hubiere.',b:'Al Ministerio Fiscal.',c:'Al representante legal de cada una de las partes.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 772.2 LECrim establece que junto al atestado se remitirá copia al abogado del detenido si lo hubiere, al Ministerio Fiscal, y al representante legal de cada parte.'}}
,{n:206,q:'Teniendo en cuenta el órgano competente, el destino del atestado será:',o:{a:'El Juzgado de Instrucción de Guardia como regla general.',b:'El Juzgado de Violencia sobre la mujer, si se trata de delitos de violencia doméstica o de género.',c:'El Fiscal de Menores (y copia al Juzgado de Menores) cuando se trate de menores de catorce a dieciocho años.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El destino del atestado varía según el órgano competente: Juzgado de Instrucción de guardia en general, Juzgado de Violencia en casos de género, y Fiscal de Menores para menores de 14 a 18 años.'}}
,{n:207,q:'De acuerdo con el artículo 297 de la LECrim:',o:{a:'Salvo caso de fuerza mayor, los funcionarios de la Policía Judicial no podrán dejar transcurrir más de 48 horas sin dar conocimiento a la Autoridad Judicial o al Ministerio Fiscal de las diligencias que hubieren practicado.',b:'Los atestados que redactaren y las manifestaciones que hicieren los funcionarios de Policía Judicial, a consecuencia de las averiguaciones que hubiesen practicado, se considerarán denuncias para los efectos legales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'b',why:{b:'El art. 297 LECrim establece que los atestados y manifestaciones de los funcionarios de PJ se considerarán denuncias para efectos legales. El plazo es 24h, no 48h, por lo que solo la b es correcta.'}}
,{n:208,q:'Según el art. 297 de la LECrim, los atestados que redactaren y las manifestaciones que hicieren los funcionarios de la Policía Judicial, a consecuencia de las averiguaciones que hubieren practicado, se considerarán denuncias a los efectos legales:',o:{a:'Cierto, debiendo firmar las demás declaraciones que prestaren, que tendrán el valor de declaraciones testificales en cuanto se refieran a hechos de conocimiento propio.',b:'Cierto, con las excepciones previstas en el art. 297 bis de la LECrim.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 297 LECrim establece que los atestados se consideran denuncias, las declaraciones de los funcionarios tendrán valor testifical sobre hechos de conocimiento propio, con las excepciones del art. 297 bis.'}}
,{n:209,q:'De acuerdo con el artículo 297 de la LECrim, los funcionarios de Policía judicial:',o:{a:'Están obligados a observar estrictamente las formalidades legales en cuantas diligencias practiquen.',b:'Se abstendrán bajo su responsabilidad de usar medios de averiguación que la Ley no autorice.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 297 LECrim establece que los funcionarios de PJ están obligados a observar estrictamente las formalidades legales y a abstenerse de usar medios no autorizados por la ley.'}}
,{n:210,q:'Con respecto al valor probatorio del atestado, la Jurisprudencia entiende que sólo puede concedérsele valor de auténtico elemento probatorio:',o:{a:'Si es reiterado y ratificado en juicio oral, normalmente mediante la declaración testifical de los agentes de policía firmantes del mismo.',b:'Cuando se trate de informes de los imputados, siempre que estos hayan sido instruidos en sus derechos y hayan gozado de asistencia letrada.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'La jurisprudencia establece que el atestado solo tiene valor probatorio auténtico si es ratificado en juicio oral por los agentes, y cuando se trate de declaraciones del imputado con garantías y asistencia letrada.'}}
,{n:211,q:'Con respecto al valor probatorio del atestado, según la Jurisprudencia:',o:{a:'Existe unanimidad doctrinal al considerar que el atestado goza del valor de la denuncia, por lo que no constituye un medio, sino, en su caso, un objeto de prueba.',b:'El atestado tiene virtualidad probatoria propia cuando contiene datos objetivos y verificables (croquis, planos, huellas, fotografías, etc.), siempre que sean introducidos en el juicio oral como prueba documental.',c:'El atestado policial, con independencia de su consideración material de documento, no tiene, como regla general, el carácter de prueba documental.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'La jurisprudencia establece: valor de denuncia del atestado, virtualidad probatoria propia con datos objetivos verificables introducidos en juicio, y que no es prueba documental como regla general.'}}
,{n:212,q:'El artículo 301 de la LECrim establece que las diligencias del sumario serán reservadas y no tendrán carácter público:',o:{a:'Hasta que se abra el juicio oral, salvo excepciones determinadas en la ley.',b:'Hasta que se publique la sentencia que ponga fin al procedimiento.',c:'Hasta que adquiera firmeza la sentencia que ponga fin al procedimiento.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'El art. 301 LECrim establece que las diligencias del sumario son reservadas y sin carácter público hasta que se abra el juicio oral, salvo excepciones.'}}
,{n:213,q:'De acuerdo con el artículo 302 de la LECrim, las partes personadas en el proceso penal podrán:',o:{a:'Tomar conocimiento de las actuaciones.',b:'Intervenir en todas las diligencias del procedimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 302 LECrim establece que las partes personadas podrán tomar conocimiento de las actuaciones e intervenir en todas las diligencias del procedimiento.'}}
,{n:214,q:'Según el artículo 302 de la LECrim, si el delito fuere público, el Juez de Instrucción mediante auto podrá declararlo total o parcialmente secreto:',o:{a:'Para todas las partes personadas.',b:'Por tiempo no superior a un mes cuando resulte necesario para evitar un riesgo grave para la vida, libertad o integridad física de una persona.',c:'Por tiempo no superior a un mes cuando resulte necesario para prevenir una situación que pueda comprometer de forma grave el resultado de la investigación o del proceso.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 302 LECrim permite declarar el secreto para todas las partes por tiempo no superior a un mes cuando sea necesario para proteger la vida o integridad de personas o el resultado de la investigación.'}}
,{n:215,q:'De acuerdo con el artículo 302 de la LECrim, el secreto del sumario deberá alzarse necesariamente:',o:{a:'Al menos con 10 días de antelación a la conclusión del sumario.',b:'Al menos con 20 días de antelación a la conclusión del sumario.',c:'Al menos con 15 días de antelación a la conclusión del sumario.',d:'Al menos con un mes de antelación a la conclusión del sumario.'},correct:'a',why:{a:'El art. 302 LECrim establece que el secreto del sumario deberá alzarse al menos con 10 días de antelación a la conclusión del sumario.'}}
,{n:216,q:'Según el artículo 301 de la LECrim, el funcionario público que reveleare indebidamente el contenido del sumario:',o:{a:'Será corregido con multa de 500 a 10.000 euros.',b:'Incurrirá en la responsabilidad que el Código Penal señale en su lugar respectivo.',c:'Incurrirá en el delito previsto en el artículo 404 del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'b',why:{b:'El art. 301 LECrim establece que el funcionario que revele indebidamente el sumario incurrirá en la responsabilidad que el CP señale en su lugar respectivo.'}}
,{n:217,q:'Según el artículo 301 de la LECrim, será/n corregido/s con multa de 500 a 10.000 euros:',o:{a:'El abogado o procurador de cualquiera de las partes que revelare indebidamente el contenido del sumario.',b:'Cualquier persona que no siendo funcionario público revelare indebidamente el contenido del sumario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 301 LECrim establece que serán corregidos con multa tanto el abogado o procurador que revele el sumario como cualquier otra persona no funcionario que lo revele.'}}
,{n:218,q:'De acuerdo con el art. 326 de la LECrim, cuando el delito que se persiga haya dejado vestigios o pruebas materiales de su perpetración, el juez instructor:',o:{a:'Ordenará que se recojan y conserven para el juicio oral.',b:'Se procederá a la inspección ocular y a la descripción de todo aquello que pudiera tener relación con la existencia y naturaleza del hecho.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 326 LECrim establece que cuando el delito deje vestigios se ordenará recogerlos y conservarlos para el juicio oral, y se procederá a la inspección ocular y descripción.'}}
,{n:219,q:'Según el artículo 326 de la LECrim, cuando el delito que se persiga haya dejado vestigios o pruebas materiales de su perpetración, el juez instructor:',o:{a:'Iniciará una amplia investigación para determinar su procedencia.',b:'Los recogerá y los pondrá a disposición del Ministerio Fiscal para que lleve a cabo la acusación.',c:'Ordenará que sean analizados en el lugar de los hechos, incorporando al sumario el resultado de dichas pruebas.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'d',why:{d:'El art. 326 LECrim no establece ninguna de estas opciones. El juez ordenará recogerlos y proceder a la inspección ocular, pero no las acciones descritas en a, b o c.'}}
,{n:220,q:'Según el artículo 326 de la LECrim, el Juez instructor, a la hora de llevar a cabo la diligencia de inspección ocular:',o:{a:'Hará una descripción del lugar del delito, el sitio y estado en que se hallen los objetos que en él se encuentren.',b:'Describirá los accidentes del terreno, o situación de las habitaciones y demás detalles que puedan utilizarse, tanto para la acusación como para la defensa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 326 LECrim establece que en la inspección ocular el juez describirá el lugar del delito con el sitio y estado de los objetos, y los accidentes del terreno o situación de las habitaciones.'}}
,{n:221,q:'Según el artículo 326 de la LECrim, durante la inspección ocular, cuando se pusiera de manifiesto la existencia de huellas o vestigios cuyo análisis biológico pudiera contribuir al esclarecimiento del hecho investigado:',o:{a:'El juez instructor los recogerá y conservará para juicio oral.',b:'El juez instructor ordenará a la Policía Judicial o al médico forense que adopte las medidas necesarias para que la recogida, custodia y examen de aquellas muestras se verifique en condiciones que garanticen su autenticidad.',c:'Se ordenará a la Policía Judicial la filmación de los mismos y su posterior verificación empírica.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'b',why:{b:'El art. 326 LECrim establece que cuando haya huellas o vestigios biológicos, el juez ordenará a la PJ o al médico forense las medidas necesarias para recoger, custodiar y examinar las muestras con garantías de autenticidad.'}}
,{n:222,q:'Según el artículo 327 de la LECrim, se levantará plano del lugar o se hará retrato de las personas que hubiesen sido objeto del delito, o la copia o diseño de los efectos o instrumentos del mismo que se hubiesen hallado:',o:{a:'Cuando existan delitos conexos.',b:'Cuando fuere conveniente para mayor claridad o comprobación de los hechos.',c:'En los delitos cometidos por bandas armadas o elementos terroristas.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 327 LECrim establece que se levantará plano o retrato cuando existan delitos conexos, cuando convenga para mayor claridad o comprobación, y en delitos de bandas armadas o terrorismo.'}}
,{n:223,q:'Según el artículo 327 de la LECrim, en la diligencia de inspección ocular, el juez instructor deberá describir los vestigios que el delincuente haya dejado y consultará el parecer de peritos sobre la manera, instrumentos, medios o tiempo de la ejecución del delito:',o:{a:'Cuando se tratare de robo o de cualquier otro delito cometido con fractura, escalamiento o violencia.',b:'En aquellos casos en que el médico forense no pudiera determinar la causa de la muerte.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 327 LECrim establece que la descripción de vestigios y consulta de peritos sobre el modo de ejecución procede en casos de robo con fractura o violencia y cuando el médico forense no pueda determinar la causa de muerte.'}}
,{n:224,q:'Según el artículo 329 de la LECrim, para llevar a cabo la diligencia de inspección ocular, el juez instructor podrá ordenar:',o:{a:'Que no se ausenten, durante la diligencia de descripción, las personas que hubiesen sido halladas en el lugar del delito.',b:'Que comparezcan inmediatamente las personas que se encontrasen en cualquier otro sitio próximo, recibiendo a todas, separadamente, la oportuna declaración.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'},correct:'c',why:{c:'El art. 329 LECrim establece que el juez puede ordenar que no se ausenten quienes estén en el lugar del delito y que comparezcan quienes se encuentren en lugares próximos para declarar separadamente.'}}
,{n:225,q:'Según el artículo 330 de la LECrim, cuando no hayan quedado huellas o vestigios del delito que hubiese dado lugar al sumario, el juez instructor:',o:{a:'Averiguará y hará constar si la desaparición de las pruebas materiales ha ocurrido natural, casual o intencionadamente.',b:'Ordenará su inmediato aseguramiento del sospechoso, adoptando medidas cautelares.',c:'Ordenará a la Policía Judicial que lleve a cabo una minuciosa inspección ocular con la finalidad de localizar otras huellas y restos.',d:'Todas las preguntas anteriores son correctas.'},correct:'a',why:{a:'El art. 330 LECrim establece que cuando no hayan quedado huellas o vestigios del delito, el juez averiguará y hará constar si la desaparición fue natural, casual o intencionada.'}}
,{n:226,q:'Según el artículo 330 de la LECrim, cuando no hayan quedado huellas o vestigios del delito que hubiese dado lugar al sumario, el juez instructor además:',o:{a:'Ordenará al Letrado de la Administración de Justicia que levante acta dejando constancia de estos extremos.',b:'Ordenará el sobreseimiento del procedimiento, si no hubiesen otras pruebas que sustentasen la acusación criminal.',c:'Recogerá y consignará en el sumario las pruebas de cualquier clase que se puedan adquirir acerca de la perpetración del delito.',d:'Todas las respuestas anteriores son correctas.'},correct:'c',why:{c:'El art. 330 LECrim también establece que el juez recogerá y consignará en el sumario las pruebas de cualquier clase que puedan adquirirse sobre la perpetración del delito.'}}
,{n:227,q:'Según el artículo 331 de la LECrim, cuando el delito fuere de los que no dejan huellas en su perpetración, el juez instructor:',o:{a:'Deberá dictar sentencia absolutoria.',b:'Procurará hacer constar, por declaraciones de testigos y demás medios de comprobación, la ejecución del delito y sus circunstancias.',c:'Ordenará, como primera diligencia la declaración del sospechoso.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'b',why:{b:'El art. 331 LECrim establece que cuando el delito no deje huellas, el juez procurará hacer constar por declaraciones de testigos y demás medios de comprobación la ejecución del delito y sus circunstancias.'}}
,{n:228,q:'Según el artículo 331 de la LECrim, cuando el delito fuere de los que no dejan huellas en su perpetración, el juez instructor también:',o:{a:'Procurará hacer constar, por declaraciones de testigos y demás medios de comprobación, la preexistencia de la cosa, cuando el delito hubiese tenido por objeto la sustracción de la misma.',b:'Ordenará a la Policía Judicial que lleve a cabo una minuciosa inspección ocular con la finalidad de localizar otras huellas.',c:'Solicitará una pericial para determinar las causas de esta ausencia de huellas.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'El art. 331 LECrim también establece que el juez procurará hacer constar la preexistencia de la cosa cuando el delito haya consistido en la sustracción de la misma.'}}
,{n:229,q:'De acuerdo con el artículo 332 de la LECrim, todas las diligencias de inspección ocular:',o:{a:'Se extenderán por escrito en el mismo acto.',b:'Serán firmadas por el juez instructor y el Fiscal, si asistiera al acto.',c:'Serán firmadas por el Secretario y las personas que se hallaren presentes.',d:'Todas las respuestas anteriores son correctas.'},correct:'d',why:{d:'El art. 332 LECrim establece que todas las diligencias de inspección ocular se extenderán por escrito en el mismo acto, serán firmadas por el juez y el Fiscal si asiste, y por el Secretario y los presentes.'}}
,{n:230,q:'De acuerdo con el artículo 333 de la LECrim, si en el momento de practicarse la diligencia de inspección ocular hubiese alguna persona declarada procesada como presunta autora del hecho punible:',o:{a:'Podrá presenciar esta diligencia, sola o asistida por el defensor que eligiese, pudiendo hacer las observaciones que estime conveniente.',b:'Deberá constituir fianza bastante a juicio de la autoridad que instruya el procedimiento.',c:'Será informada de los hechos que se le atribuyen y de las razones de su privación de libertad.',d:'Ninguna de las respuestas anteriores es correcta.'},correct:'a',why:{a:'El art. 333 LECrim establece que si existe persona procesada podrá presenciar la diligencia de inspección ocular, sola o asistida por el defensor que elija, pudiendo hacer observaciones.'}}
];
